/// BFV parameter set.
#[cfg_attr(feature = "json", derive(JsonSerialize, JsonDeserialize))]
#[derive(Clone, Copy, Debug, PartialEq, Eq, Encode, Decode, IntoSchema)]
pub struct BfvParameters {
    /// Ring degree `n` for `Z_q[x] / (x^n + 1)`. Must be a power of two.
    pub polynomial_degree: u16,
    /// Ciphertext modulus `q`.
    pub ciphertext_modulus: u64,
    /// Plaintext modulus `t`.
    pub plaintext_modulus: u64,
    /// Base-2 logarithm of the relinearization decomposition base.
    pub decomposition_base_log: u8,
}

impl BfvParameters {
    /// Validate the parameter set.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the parameter set is internally inconsistent.
    pub fn validate(&self) -> Result<(), BfvError> {
        let n = usize::from(self.polynomial_degree);
        if n < 2 || !n.is_power_of_two() {
            return Err(BfvError::InvalidParameters(
                "polynomial_degree must be a power of two and at least 2".to_owned(),
            ));
        }
        if self.plaintext_modulus < 2 {
            return Err(BfvError::InvalidParameters(
                "plaintext_modulus must be at least 2".to_owned(),
            ));
        }
        if self.ciphertext_modulus <= self.plaintext_modulus {
            return Err(BfvError::InvalidParameters(
                "ciphertext_modulus must be greater than plaintext_modulus".to_owned(),
            ));
        }
        if !self
            .ciphertext_modulus
            .is_multiple_of(self.plaintext_modulus)
        {
            return Err(BfvError::InvalidParameters(
                "ciphertext_modulus must be divisible by plaintext_modulus".to_owned(),
            ));
        }
        let error_headroom = self
            .plaintext_modulus
            .checked_mul(u64::from(BFV_ERROR_MULTIPLE_BOUND) * 2)
            .ok_or_else(|| {
                BfvError::InvalidParameters(
                    "plaintext-multiple error profile exceeds ciphertext modulus bounds".to_owned(),
                )
            })?;
        if self.ciphertext_modulus <= error_headroom {
            return Err(BfvError::InvalidParameters(format!(
                "ciphertext_modulus must exceed 2 * plaintext_modulus * BFV error bound {BFV_ERROR_MULTIPLE_BOUND}"
            )));
        }
        if self.decomposition_base_log == 0 || self.decomposition_base_log > 16 {
            return Err(BfvError::InvalidParameters(
                "decomposition_base_log must be within 1..=16".to_owned(),
            ));
        }
        let max_raw_coefficient = u128::from(self.polynomial_degree)
            .checked_mul(u128::from(self.ciphertext_modulus))
            .and_then(|value| value.checked_mul(u128::from(self.ciphertext_modulus)))
            .ok_or_else(|| {
                BfvError::InvalidParameters(
                    "parameter set exceeds the deterministic BFV exact-arithmetic raw coefficient bounds"
                        .to_owned(),
                )
            })?;
        let max_scaled_coefficient = max_raw_coefficient
            .checked_mul(u128::from(self.plaintext_modulus))
            .ok_or_else(|| {
                BfvError::InvalidParameters(
                    "parameter set exceeds the deterministic BFV exact-arithmetic scaled coefficient bounds"
                        .to_owned(),
                )
            })?;
        if max_scaled_coefficient > i128::MAX as u128 {
            return Err(BfvError::InvalidParameters(
                "parameter set exceeds the deterministic BFV exact-arithmetic overflow bounds"
                    .to_owned(),
            ));
        }
        Ok(())
    }

    /// Report the polynomial-convolution backend used for BFV ring products.
    #[must_use]
    pub fn convolution_backend(&self) -> BfvConvolutionBackend {
        #[cfg(not(feature = "bfv-accel"))]
        let _ = self;

        #[cfg(feature = "bfv-accel")]
        {
            let Some(convolution_len) = self.degree().checked_mul(2) else {
                return BfvConvolutionBackend::ScalarSchoolbook;
            };
            if convolution_len == 0 {
                return BfvConvolutionBackend::ScalarSchoolbook;
            }
            let required_log = convolution_len.ilog2();
            if convolution_len.is_power_of_two()
                && CRT_NTT_PRIMES
                    .iter()
                    .all(|prime| prime.max_power_of_two >= required_log)
            {
                return BfvConvolutionBackend::CrtNtt;
            }
        }
        BfvConvolutionBackend::ScalarSchoolbook
    }

    fn degree(&self) -> usize {
        usize::from(self.polynomial_degree)
    }

    fn decomposition_base(&self) -> u64 {
        1_u64 << self.decomposition_base_log
    }

    fn decomposition_digits(&self) -> Result<usize, BfvError> {
        self.validate()?;
        let mut digits = 0_usize;
        let mut covered = 1_u128;
        let base = u128::from(self.decomposition_base());
        let modulus = u128::from(self.ciphertext_modulus);
        while covered < modulus {
            covered = covered.checked_mul(base).ok_or_else(|| {
                BfvError::InvalidParameters(
                    "BFV decomposition digit coverage exceeds deterministic limits".to_owned(),
                )
            })?;
            digits = digits.checked_add(1).ok_or_else(|| {
                BfvError::InvalidParameters(
                    "BFV decomposition digit count exceeds deterministic limits".to_owned(),
                )
            })?;
        }
        Ok(digits.max(1))
    }
}

/// BFV RNS coefficient-modulus chain.
#[cfg_attr(feature = "json", derive(JsonSerialize, JsonDeserialize))]
#[derive(Clone, Debug, PartialEq, Eq, Encode, Decode, IntoSchema)]
pub struct BfvRnsModulusChain {
    /// Ordered RNS coefficient-modulus limbs.
    pub moduli: Vec<u64>,
}

impl BfvRnsModulusChain {
    /// Validate this RNS chain against a BFV parameter set.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the parameter set or modulus chain is
    /// malformed, noncanonical, unsupported for NTT evaluation, or too small to
    /// cover the parameter-set ciphertext modulus.
    pub fn validate_for_parameters(&self, params: &BfvParameters) -> Result<(), BfvError> {
        validate_bfv_rns_modulus_chain(self, params).map(|_| ())
    }

    /// Validate that every RNS limb has a concrete primitive root for
    /// negacyclic NTT multiplication at this parameter set's ring degree.
    ///
    /// Registered production limbs use the precomputed root table; other
    /// structurally valid prime limbs must support bounded deterministic root
    /// discovery.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the chain is malformed or a limb has no
    /// supported primitive root for the required `2n`-th order.
    pub fn validate_negacyclic_ntt_support(&self, params: &BfvParameters) -> Result<(), BfvError> {
        self.validate_for_parameters(params)
    }

    /// Validate that this RNS chain also fits the current exact-lift fallback.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the chain is not a valid RNS chain for the
    /// parameter set, or when its product exceeds the deterministic
    /// exact-arithmetic bounds used before the full BFV-RNS engine lands.
    pub fn validate_exact_lift_compatibility(
        &self,
        params: &BfvParameters,
    ) -> Result<(), BfvError> {
        let product = validate_bfv_rns_modulus_chain(self, params)?;
        validate_rns_exact_lift_product_bound(params, product)
    }

    /// Validate that the chain is wide enough for naive exact-lift
    /// ciphertext-modulus addition.
    ///
    /// This is a guard for temporary scalar/RNS fallback code, not a
    /// requirement for the future full BFV-RNS evaluator. A product-ring RNS
    /// addition can be reduced back into `Z_q` without ambiguity only when the
    /// chain product covers every possible unreduced sum of two `Z_q`
    /// coefficients.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the chain is malformed or too narrow for this
    /// exact fallback.
    pub fn validate_exact_ciphertext_modulus_addition_coverage(
        &self,
        params: &BfvParameters,
    ) -> Result<(), BfvError> {
        let product = validate_bfv_rns_modulus_chain(self, params)?;
        let required = exact_ciphertext_modulus_addition_rns_bound(params)?;
        if product < required {
            return Err(BfvError::InvalidParameters(format!(
                "BFV RNS modulus-chain product {product} does not cover exact ciphertext-modulus addition bound {required}"
            )));
        }
        Ok(())
    }

    /// Validate that the chain is wide enough for naive exact-lift
    /// ciphertext-modulus negacyclic multiplication.
    ///
    /// This guard rejects using product-ring RNS multiplication as a drop-in
    /// replacement for `Z_q[x] / (x^n + 1)` multiplication unless the chain can
    /// uniquely represent the signed unreduced coefficient range. The
    /// registered RAM-LFE chain satisfies this exact-evaluator bridge bound,
    /// but this remains separate from the future bounded-noise BFV-RNS
    /// evaluator.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the chain is malformed or too narrow for this
    /// exact fallback.
    pub fn validate_exact_ciphertext_modulus_negacyclic_product_coverage(
        &self,
        params: &BfvParameters,
    ) -> Result<(), BfvError> {
        let product = validate_bfv_rns_modulus_chain(self, params)?;
        let required = exact_ciphertext_modulus_negacyclic_product_rns_bound(params)?;
        if product < required {
            return Err(BfvError::InvalidParameters(format!(
                "BFV RNS modulus-chain product {product} does not cover exact ciphertext-modulus negacyclic product bound {required}"
            )));
        }
        Ok(())
    }

    /// Validate exact coverage for a sum of centered negacyclic products.
    ///
    /// This is the guard used by rounded BFV cross terms such as
    /// `c0_left*c1_right + c1_left*c0_right`: the RNS chain must represent the
    /// signed sum without aliasing before the deterministic `t/q`
    /// scale-and-round step.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the chain is malformed, `product_count` is
    /// zero, or the chain is too narrow for this exact fallback.
    pub fn validate_exact_ciphertext_modulus_negacyclic_product_sum_coverage(
        &self,
        params: &BfvParameters,
        product_count: u16,
    ) -> Result<(), BfvError> {
        let product = validate_bfv_rns_modulus_chain(self, params)?;
        let required =
            exact_ciphertext_modulus_negacyclic_product_sum_rns_bound(params, product_count)?;
        if product < required {
            return Err(BfvError::InvalidParameters(format!(
                "BFV RNS modulus-chain product {product} does not cover exact ciphertext-modulus negacyclic product-sum bound {required}"
            )));
        }
        Ok(())
    }

    /// Return the checked product of all RNS limbs.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the chain is empty or the product does not fit
    /// into `u128`.
    pub fn product(&self) -> Result<u128, BfvError> {
        checked_rns_modulus_product(&self.moduli)
    }

    /// Return a stable digest over this RNS modulus chain.
    ///
    /// # Errors
    /// Returns [`BfvError`] when validation or canonical encoding fails.
    pub fn digest_for_parameters(&self, params: &BfvParameters) -> Result<Hash, BfvError> {
        self.validate_for_parameters(params)?;
        let bytes = norito::to_bytes(self).map_err(|err| {
            BfvError::InvalidParameters(format!("RNS modulus-chain encoding failed: {err}"))
        })?;
        Ok(Hash::new_from_chunks(&[
            BFV_RNS_MODULUS_CHAIN_DIGEST_DOMAIN,
            bytes.as_slice(),
        ]))
    }

    /// Decompose a BFV polynomial into limb-major RNS residues.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the chain, parameter set, or source
    /// polynomial shape is invalid.
    pub fn decompose_polynomial(
        &self,
        params: &BfvParameters,
        coefficients: &[u64],
    ) -> Result<BfvRnsPolynomial, BfvError> {
        self.validate_for_parameters(params)?;
        validate_poly(params, coefficients, "RNS source polynomial")?;
        let residues_by_limb = self
            .moduli
            .iter()
            .map(|&modulus| {
                coefficients
                    .iter()
                    .map(|&coefficient| coefficient % modulus)
                    .collect()
            })
            .collect();
        Ok(BfvRnsPolynomial { residues_by_limb })
    }

    /// Decompose a `Z_q` polynomial into centered limb-major RNS residues.
    ///
    /// Coefficients above the centered modulus midpoint are first interpreted
    /// as negative representatives. This is the decomposition used by rounded
    /// BFV raw-product reconstruction, where `q - a` must multiply as `-a`
    /// before `t/q` scale-and-rounding.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the chain, parameter set, or source polynomial
    /// shape is invalid.
    pub fn decompose_centered_ciphertext_modulus_polynomial(
        &self,
        params: &BfvParameters,
        coefficients: &[u64],
    ) -> Result<BfvRnsPolynomial, BfvError> {
        self.validate_for_parameters(params)?;
        validate_poly(params, coefficients, "centered RNS source polynomial")?;
        let residues_by_limb = self
            .moduli
            .iter()
            .map(|&modulus| {
                coefficients
                    .iter()
                    .map(|&coefficient| {
                        mod_q(center_lift(coefficient, params.ciphertext_modulus), modulus)
                    })
                    .collect()
            })
            .collect();
        Ok(BfvRnsPolynomial { residues_by_limb })
    }

    /// Decompose a key-switch component into base digits in this RNS chain.
    ///
    /// Each returned RNS polynomial contains one base-`2^decomposition_base_log`
    /// digit of `switching_component`, ordered from least- to
    /// most-significant. Keeping these digit polynomials in RNS form is the
    /// bridge needed for basis-extension-aware key switching.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the chain, parameter set, source polynomial, or
    /// decomposition profile is invalid, or when the chain cannot represent one
    /// base-decomposition digit.
    pub fn decompose_key_switch_component_polynomial(
        &self,
        params: &BfvParameters,
        switching_component: &[u64],
    ) -> Result<Vec<BfvRnsPolynomial>, BfvError> {
        self.validate_for_parameters(params)?;
        let product = self.product()?;
        let base = u128::from(params.decomposition_base());
        if product < base {
            return Err(BfvError::InvalidParameters(format!(
                "RNS key-switch component decomposition chain product {product} does not cover decomposition base {base}"
            )));
        }
        validate_poly(
            params,
            switching_component,
            "RNS key-switch component polynomial",
        )?;
        decompose_poly(params, switching_component)?
            .into_iter()
            .map(|digit| self.decompose_polynomial(params, &digit))
            .collect()
    }

    /// Reconstruct coefficient values from limb-major RNS residues.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the chain, parameter set, or residue shape is
    /// invalid, or when CRT reconstruction overflows `u128`.
    pub fn reconstruct_polynomial(
        &self,
        params: &BfvParameters,
        polynomial: &BfvRnsPolynomial,
    ) -> Result<Vec<u128>, BfvError> {
        self.validate_for_parameters(params)?;
        validate_rns_polynomial(params, self, polynomial)?;
        (0..params.degree())
            .map(|index| {
                let residues = polynomial
                    .residues_by_limb
                    .iter()
                    .map(|limb| limb[index])
                    .collect::<Vec<_>>();
                reconstruct_rns_coefficient(&residues, &self.moduli)
            })
            .collect()
    }

    /// Extend an RNS polynomial from this chain into another modulus chain.
    ///
    /// This is an exact CRT basis-extension bridge: coefficients are
    /// reconstructed from the source chain, then reduced into each target limb.
    /// The target chain product must cover the source chain product so the
    /// converted polynomial can be reconstructed without aliasing. It remains a
    /// deterministic reconstructable bridge; key-switch paths that only need
    /// target residues use [`Self::basis_extend_polynomial_target_limbs`].
    ///
    /// # Errors
    /// Returns [`BfvError`] when either chain is malformed for the parameter
    /// set, when the source polynomial shape is invalid, when the target chain
    /// cannot exactly cover the source chain product, or when CRT
    /// reconstruction overflows.
    pub fn basis_extend_polynomial(
        &self,
        params: &BfvParameters,
        polynomial: &BfvRnsPolynomial,
        target_chain: &BfvRnsModulusChain,
    ) -> Result<BfvRnsPolynomial, BfvError> {
        self.validate_for_parameters(params)?;
        target_chain.validate_for_parameters(params)?;
        let source_product = self.product()?;
        let target_product = target_chain.product()?;
        if target_product < source_product {
            return Err(BfvError::InvalidParameters(format!(
                "BFV RNS basis-extension target product {target_product} does not cover source product {source_product}"
            )));
        }
        validate_rns_polynomial(params, self, polynomial)?;
        let coefficients = self.reconstruct_polynomial(params, polynomial)?;
        let residues_by_limb = target_chain
            .moduli
            .iter()
            .map(|&modulus| {
                coefficients
                    .iter()
                    .map(|&coefficient| reduce_u128_to_u64_mod(coefficient, modulus))
                    .collect::<Result<Vec<_>, BfvError>>()
            })
            .collect::<Result<Vec<_>, BfvError>>()?;
        Ok(BfvRnsPolynomial { residues_by_limb })
    }

    /// Extend an RNS polynomial directly into target-chain limbs.
    ///
    /// This is the deterministic target-limb basis-extension boundary needed by
    /// the BFV-RNS evaluator: coefficients are interpreted as canonical
    /// representatives modulo the source-chain product, a CRT quotient
    /// correction is computed exactly with integer arithmetic, and each target
    /// limb receives the corresponding residue. Unlike
    /// [`Self::basis_extend_polynomial`], the target chain does not need to
    /// cover the source-chain product because callers are asking only for
    /// target residues, not for later reconstruction of the full source
    /// representative from the target chain alone.
    ///
    /// # Errors
    /// Returns [`BfvError`] when either chain is malformed for the parameter
    /// set, the source polynomial shape is invalid, a CRT inverse is missing,
    /// or deterministic quotient-correction arithmetic exceeds supported
    /// bounds.
    pub fn basis_extend_polynomial_target_limbs(
        &self,
        params: &BfvParameters,
        polynomial: &BfvRnsPolynomial,
        target_chain: &BfvRnsModulusChain,
    ) -> Result<BfvRnsPolynomial, BfvError> {
        self.validate_for_parameters(params)?;
        target_chain.validate_for_parameters(params)?;
        validate_rns_polynomial(params, self, polynomial)?;

        let source_product = self.product()?;
        let source_limb_data = self
            .moduli
            .iter()
            .map(|&source_modulus| {
                let source_basis = source_product / u128::from(source_modulus);
                let source_basis_mod_source = reduce_u128_to_u64_mod(source_basis, source_modulus)?;
                let inverse = mod_inv_prime_u64(source_basis_mod_source, source_modulus)
                    .ok_or_else(|| {
                        BfvError::InvalidParameters(format!(
                            "BFV RNS basis-extension source limb {source_modulus} is not invertible"
                        ))
                    })?;
                Ok((source_modulus, source_basis, inverse))
            })
            .collect::<Result<Vec<_>, BfvError>>()?;

        let mut residues_by_limb =
            vec![Vec::with_capacity(params.degree()); target_chain.moduli.len()];
        for coefficient_index in 0..params.degree() {
            let mut quotient = 0_u128;
            let mut remainder = 0_u128;
            let mut crt_digits = Vec::with_capacity(source_limb_data.len());

            for (source_limb_index, &(source_modulus, source_basis, inverse)) in
                source_limb_data.iter().enumerate()
            {
                let residue = polynomial.residues_by_limb[source_limb_index][coefficient_index];
                let crt_digit = mul_mod_u64(residue, inverse, source_modulus);
                let term = source_basis
                    .checked_mul(u128::from(crt_digit))
                    .ok_or_else(|| {
                        BfvError::InvalidParameters(
                            "BFV RNS basis-extension CRT term exceeds u128".to_owned(),
                        )
                    })?;

                if remainder >= source_product - term {
                    remainder -= source_product - term;
                    quotient = quotient.checked_add(1).ok_or_else(|| {
                        BfvError::InvalidParameters(
                            "BFV RNS basis-extension quotient exceeds u128".to_owned(),
                        )
                    })?;
                } else {
                    remainder += term;
                }
                crt_digits.push((crt_digit, source_basis));
            }

            for (target_limb_index, &target_modulus) in target_chain.moduli.iter().enumerate() {
                let mut target_residue = 0_u64;
                for &(crt_digit, source_basis) in &crt_digits {
                    let digit_mod_target =
                        reduce_u128_to_u64_mod(u128::from(crt_digit), target_modulus)?;
                    let basis_mod_target = reduce_u128_to_u64_mod(source_basis, target_modulus)?;
                    target_residue = add_mod_u64(
                        target_residue,
                        mul_mod_u64(digit_mod_target, basis_mod_target, target_modulus),
                        target_modulus,
                    );
                }
                let quotient_mod_target = reduce_u128_to_u64_mod(quotient, target_modulus)?;
                let source_product_mod_target =
                    reduce_u128_to_u64_mod(source_product, target_modulus)?;
                let correction = mul_mod_u64(
                    quotient_mod_target,
                    source_product_mod_target,
                    target_modulus,
                );
                residues_by_limb[target_limb_index].push(sub_mod_u64(
                    target_residue,
                    correction,
                    target_modulus,
                ));
            }
        }

        Ok(BfvRnsPolynomial { residues_by_limb })
    }

    /// Extend one canonical key-switch digit polynomial into another RNS chain.
    ///
    /// Unlike [`Self::basis_extend_polynomial`], this helper is specialized to
    /// base-decomposition digits. It reconstructs each coefficient from the
    /// source chain, verifies that the coefficient is a canonical
    /// `0..decomposition_base` digit, then reduces that digit into the target
    /// limbs. The target chain only needs to represent the decomposition base,
    /// not the full source-chain product, which is the boundary used by
    /// basis-extension-aware key switching.
    ///
    /// # Errors
    /// Returns [`BfvError`] when either chain is malformed for the parameter
    /// set, either chain cannot represent the decomposition base, the source
    /// polynomial shape is invalid, a reconstructed coefficient is not a
    /// canonical digit, or CRT reconstruction overflows.
    pub fn basis_extend_key_switch_digit_polynomial(
        &self,
        params: &BfvParameters,
        polynomial: &BfvRnsPolynomial,
        target_chain: &BfvRnsModulusChain,
    ) -> Result<BfvRnsPolynomial, BfvError> {
        self.validate_for_parameters(params)?;
        target_chain.validate_for_parameters(params)?;
        let base = u128::from(params.decomposition_base());
        let source_product = self.product()?;
        if source_product < base {
            return Err(BfvError::InvalidParameters(format!(
                "BFV RNS key-switch digit source product {source_product} does not cover decomposition base {base}"
            )));
        }
        let target_product = target_chain.product()?;
        if target_product < base {
            return Err(BfvError::InvalidParameters(format!(
                "BFV RNS key-switch digit target product {target_product} does not cover decomposition base {base}"
            )));
        }
        validate_rns_polynomial(params, self, polynomial)?;
        let coefficients = self.reconstruct_polynomial(params, polynomial)?;
        for (index, &coefficient) in coefficients.iter().enumerate() {
            if coefficient >= base {
                return Err(BfvError::ShapeMismatch(format!(
                    "RNS key-switch digit coefficient[{index}] {coefficient} exceeds decomposition base {base}"
                )));
            }
        }
        let residues_by_limb = target_chain
            .moduli
            .iter()
            .map(|&modulus| {
                coefficients
                    .iter()
                    .map(|&coefficient| reduce_u128_to_u64_mod(coefficient, modulus))
                    .collect::<Result<Vec<_>, BfvError>>()
            })
            .collect::<Result<Vec<_>, BfvError>>()?;
        Ok(BfvRnsPolynomial { residues_by_limb })
    }

    /// Add two RNS polynomials coefficient-wise in the chain product ring.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the chain, parameter set, or either operand
    /// is malformed.
    pub fn add_rns_polynomials(
        &self,
        params: &BfvParameters,
        lhs: &BfvRnsPolynomial,
        rhs: &BfvRnsPolynomial,
    ) -> Result<BfvRnsPolynomial, BfvError> {
        validate_rns_polynomial_pair(params, self, lhs, rhs)?;
        let residues_by_limb = lhs
            .residues_by_limb
            .iter()
            .zip(&rhs.residues_by_limb)
            .zip(&self.moduli)
            .map(|((lhs_limb, rhs_limb), &modulus)| {
                lhs_limb
                    .iter()
                    .zip(rhs_limb)
                    .map(|(&left, &right)| add_mod_u64(left, right, modulus))
                    .collect()
            })
            .collect();
        Ok(BfvRnsPolynomial { residues_by_limb })
    }

    /// Multiply two RNS polynomials in `Z_Q[x] / (x^n + 1)`.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the chain, parameter set, or either operand
    /// is malformed.
    pub fn multiply_rns_polynomials_negacyclic(
        &self,
        params: &BfvParameters,
        lhs: &BfvRnsPolynomial,
        rhs: &BfvRnsPolynomial,
    ) -> Result<BfvRnsPolynomial, BfvError> {
        validate_rns_polynomial_pair(params, self, lhs, rhs)?;
        let residues_by_limb = lhs
            .residues_by_limb
            .iter()
            .zip(&rhs.residues_by_limb)
            .zip(&self.moduli)
            .map(|((lhs_limb, rhs_limb), &modulus)| {
                multiply_rns_limb_negacyclic(params, lhs_limb, rhs_limb, modulus)
            })
            .collect();
        Ok(BfvRnsPolynomial { residues_by_limb })
    }

    /// Multiply an RNS polynomial by a `Z_q` polynomial through an exact RNS corridor.
    ///
    /// This is the key-switch digit product primitive: the left operand is
    /// already represented in this RNS chain, while the right operand is a
    /// ciphertext-modulus polynomial such as an evaluation-key component. The
    /// product is reconstructed exactly and reduced back into `Z_q`.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the chain is malformed, too narrow for exact
    /// `Z_q` negacyclic multiplication, or either operand is malformed.
    pub fn multiply_rns_polynomial_by_ciphertext_modulus_polynomial_negacyclic_exact(
        &self,
        params: &BfvParameters,
        lhs: &BfvRnsPolynomial,
        rhs: &[u64],
    ) -> Result<Vec<u64>, BfvError> {
        self.validate_exact_ciphertext_modulus_negacyclic_product_coverage(params)?;
        validate_rns_polynomial(params, self, lhs)?;
        validate_poly(params, rhs, "RNS exact-multiply rhs polynomial")?;

        let chain_product = self.product()?;
        let centered_abs_bound = exact_ciphertext_modulus_negacyclic_product_abs_bound(params)?;
        let rhs_rns = self.decompose_polynomial(params, rhs)?;
        let product_rns = self.multiply_rns_polynomials_negacyclic(params, lhs, &rhs_rns)?;
        self.reconstruct_polynomial(params, &product_rns)?
            .into_iter()
            .map(|coefficient| {
                reduce_centered_rns_value_to_u64_mod(
                    coefficient,
                    chain_product,
                    centered_abs_bound,
                    params.ciphertext_modulus,
                )
            })
            .collect()
    }

    /// Multiply two `Z_q` polynomials and return exact centered raw coefficients.
    ///
    /// Unlike [`Self::multiply_ciphertext_modulus_polynomials_negacyclic_exact`],
    /// this does not reduce the reconstructed negacyclic product back into
    /// `Z_q`. It returns the signed centered raw product needed by rounded BFV
    /// multiplication before the deterministic `t/q` scale-and-round step.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the chain is malformed, too narrow for exact
    /// centered reconstruction, either polynomial is malformed, or the centered
    /// product does not fit deterministic signed integer bounds.
    pub fn multiply_ciphertext_modulus_centered_polynomials_negacyclic_raw_exact(
        &self,
        params: &BfvParameters,
        lhs: &[u64],
        rhs: &[u64],
    ) -> Result<Vec<i128>, BfvError> {
        self.validate_exact_ciphertext_modulus_negacyclic_product_sum_coverage(params, 1)?;
        validate_poly(params, lhs, "RNS centered multiply lhs polynomial")?;
        validate_poly(params, rhs, "RNS centered multiply rhs polynomial")?;

        let chain_product = self.product()?;
        let centered_abs_bound =
            exact_centered_ciphertext_modulus_negacyclic_product_abs_bound(params)?;
        let lhs_rns = self.decompose_centered_ciphertext_modulus_polynomial(params, lhs)?;
        let rhs_rns = self.decompose_centered_ciphertext_modulus_polynomial(params, rhs)?;
        let product_rns = self.multiply_rns_polynomials_negacyclic(params, &lhs_rns, &rhs_rns)?;
        self.reconstruct_polynomial(params, &product_rns)?
            .into_iter()
            .map(|coefficient| {
                reduce_centered_rns_value_to_i128(coefficient, chain_product, centered_abs_bound)
            })
            .collect()
    }

    /// Multiply two `Z_q` polynomials and return rounded BFV product coefficients.
    ///
    /// This is the RNS exact bridge for the rounded BFV multiplication
    /// boundary: raw centered products are evaluated through this RNS chain,
    /// reconstructed exactly, then deterministically scaled by `t/q` and
    /// rounded back into `Z_q`. It is still an exact reconstruction fallback,
    /// not the final approximate BFV-RNS scale-and-round pipeline.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the chain is malformed, too narrow for exact
    /// centered reconstruction, either polynomial is malformed, or the
    /// product/scaling arithmetic exceeds deterministic bounds.
    pub fn multiply_ciphertext_modulus_centered_polynomials_negacyclic_scale_round_exact(
        &self,
        params: &BfvParameters,
        lhs: &[u64],
        rhs: &[u64],
    ) -> Result<Vec<u64>, BfvError> {
        self.validate_exact_ciphertext_modulus_negacyclic_product_sum_coverage(params, 1)?;
        validate_poly(params, lhs, "RNS scale-round multiply lhs polynomial")?;
        validate_poly(params, rhs, "RNS scale-round multiply rhs polynomial")?;

        let lhs_rns = self.decompose_centered_ciphertext_modulus_polynomial(params, lhs)?;
        let rhs_rns = self.decompose_centered_ciphertext_modulus_polynomial(params, rhs)?;
        let product_rns = self.multiply_rns_polynomials_negacyclic(params, &lhs_rns, &rhs_rns)?;
        self.scale_round_centered_product_polynomial_exact(params, &product_rns)
    }

    /// Scale-round a centered RNS product polynomial into rounded BFV `Z_q` coefficients.
    ///
    /// The input polynomial is interpreted as a centered negacyclic product
    /// represented in this chain's product ring. The chain must cover the same
    /// exact product bound as
    /// [`Self::multiply_ciphertext_modulus_centered_polynomials_negacyclic_raw_exact`].
    /// This is the explicit exact-RNS scale-round boundary used until the
    /// approximate BFV-RNS pipeline lands.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the chain is malformed, too narrow for exact
    /// centered reconstruction, the RNS polynomial shape is invalid, or the
    /// product/scaling arithmetic exceeds deterministic bounds.
    pub fn scale_round_centered_product_polynomial_exact(
        &self,
        params: &BfvParameters,
        product: &BfvRnsPolynomial,
    ) -> Result<Vec<u64>, BfvError> {
        self.validate_exact_ciphertext_modulus_negacyclic_product_sum_coverage(params, 1)?;
        validate_rns_polynomial(params, self, product)?;
        let chain_product = self.product()?;
        let centered_abs_bound =
            exact_centered_ciphertext_modulus_negacyclic_product_abs_bound(params)?;
        self.reconstruct_polynomial(params, product)?
            .into_iter()
            .map(|coefficient| {
                reduce_centered_rns_value_to_i128(coefficient, chain_product, centered_abs_bound)
                    .and_then(|coefficient| {
                        scale_round_raw_product_coefficient(params, coefficient)
                    })
            })
            .collect()
    }

    /// Add two centered RNS product polynomials and scale-round the sum.
    ///
    /// Both inputs are interpreted as centered negacyclic products represented
    /// in this chain's product ring. The chain must cover the two-product
    /// signed sum exactly before the rounded BFV `t/q` boundary.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the chain is malformed, too narrow for the
    /// exact two-product sum, either RNS polynomial shape is invalid, or the
    /// product/scaling arithmetic exceeds deterministic bounds.
    pub fn scale_round_add_centered_product_polynomials_exact(
        &self,
        params: &BfvParameters,
        lhs: &BfvRnsPolynomial,
        rhs: &BfvRnsPolynomial,
    ) -> Result<Vec<u64>, BfvError> {
        self.validate_exact_ciphertext_modulus_negacyclic_product_sum_coverage(params, 2)?;
        validate_rns_polynomial_pair(params, self, lhs, rhs)?;
        let sum = self.add_rns_polynomials(params, lhs, rhs)?;
        let chain_product = self.product()?;
        let centered_abs_bound =
            exact_ciphertext_modulus_negacyclic_product_sum_abs_bound(params, 2)?;
        self.reconstruct_polynomial(params, &sum)?
            .into_iter()
            .map(|coefficient| {
                reduce_centered_rns_value_to_i128(coefficient, chain_product, centered_abs_bound)
                    .and_then(|coefficient| {
                        scale_round_raw_product_coefficient(params, coefficient)
                    })
            })
            .collect()
    }

    /// Add two ciphertext-modulus polynomials through an exact RNS corridor.
    ///
    /// This helper is intentionally guarded by
    /// [`Self::validate_exact_ciphertext_modulus_addition_coverage`]. It is
    /// suitable for exact fallback/evaluator tests whose chain product is wide
    /// enough to reconstruct every unreduced `Z_q` coefficient sum before
    /// reducing back modulo `q`.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the chain is malformed, too narrow for exact
    /// `Z_q` addition, or either polynomial is malformed.
    pub fn add_ciphertext_modulus_polynomials_exact(
        &self,
        params: &BfvParameters,
        lhs: &[u64],
        rhs: &[u64],
    ) -> Result<Vec<u64>, BfvError> {
        self.validate_exact_ciphertext_modulus_addition_coverage(params)?;
        validate_poly(params, lhs, "RNS exact-add lhs polynomial")?;
        validate_poly(params, rhs, "RNS exact-add rhs polynomial")?;

        let lhs_rns = self.decompose_polynomial(params, lhs)?;
        let rhs_rns = self.decompose_polynomial(params, rhs)?;
        let sum_rns = self.add_rns_polynomials(params, &lhs_rns, &rhs_rns)?;
        self.reconstruct_polynomial(params, &sum_rns)?
            .into_iter()
            .map(|coefficient| reduce_u128_to_u64_mod(coefficient, params.ciphertext_modulus))
            .collect()
    }

    /// Multiply two ciphertext-modulus polynomials through an exact RNS corridor.
    ///
    /// This helper is intentionally guarded by
    /// [`Self::validate_exact_ciphertext_modulus_negacyclic_product_coverage`].
    /// Negacyclic products contain signed wraparound terms, so reconstruction
    /// uses the unique centered representative before reducing back modulo
    /// `q`.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the chain is malformed, too narrow for exact
    /// `Z_q` negacyclic multiplication, or either polynomial is malformed.
    pub fn multiply_ciphertext_modulus_polynomials_negacyclic_exact(
        &self,
        params: &BfvParameters,
        lhs: &[u64],
        rhs: &[u64],
    ) -> Result<Vec<u64>, BfvError> {
        self.validate_exact_ciphertext_modulus_negacyclic_product_coverage(params)?;
        validate_poly(params, lhs, "RNS exact-multiply lhs polynomial")?;
        validate_poly(params, rhs, "RNS exact-multiply rhs polynomial")?;

        let chain_product = self.product()?;
        let centered_abs_bound = exact_ciphertext_modulus_negacyclic_product_abs_bound(params)?;
        let lhs_rns = self.decompose_polynomial(params, lhs)?;
        let rhs_rns = self.decompose_polynomial(params, rhs)?;
        let product_rns = self.multiply_rns_polynomials_negacyclic(params, &lhs_rns, &rhs_rns)?;
        self.reconstruct_polynomial(params, &product_rns)?
            .into_iter()
            .map(|coefficient| {
                reduce_centered_rns_value_to_u64_mod(
                    coefficient,
                    chain_product,
                    centered_abs_bound,
                    params.ciphertext_modulus,
                )
            })
            .collect()
    }
}

