fn validate_bfv_full_bootstrap_release_audit_proof_profile_shape_v1(
    profile: &BfvFullBootstrapReleaseAuditProofProfileV1,
) -> Result<(), BfvError> {
    if profile.version != BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PROOF_PROFILE_VERSION_V1 {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap release audit proof profile version {} does not match canonical version {}",
            profile.version, BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PROOF_PROFILE_VERSION_V1
        )));
    }
    if profile.field_count != BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PROOF_PROFILE_FIELD_COUNT_V1 {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap release audit proof profile field count {} does not match canonical count {}",
            profile.field_count, BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PROOF_PROFILE_FIELD_COUNT_V1
        )));
    }
    if profile.backend != BFV_FULL_BOOTSTRAP_PROOF_BACKEND_V1 {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit proof profile backend mismatch".to_owned(),
        ));
    }
    if profile.key_format != BFV_FULL_BOOTSTRAP_PROOF_KEY_FORMAT_V1 {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit proof profile key format mismatch".to_owned(),
        ));
    }
    if profile.proof_system != BFV_FULL_BOOTSTRAP_NATIVE_STARK_FRI_PROOF_SYSTEM_V1 {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit proof profile proof system mismatch".to_owned(),
        ));
    }
    if profile.field != BFV_FULL_BOOTSTRAP_NATIVE_STARK_FIELD_V1 {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit proof profile field mismatch".to_owned(),
        ));
    }
    validate_bfv_full_bootstrap_native_stark_fri_common_profile_v1(
        "BFV full-bootstrap release audit proof profile",
        profile.hash_fn,
        profile.n_log2,
        profile.blowup_log2,
        profile.fold_arity,
        profile.queries,
        profile.merkle_arity,
    )?;
    if profile.statement_material_version
        != BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_STATEMENT_MATERIAL_VERSION_V1
        || profile.statement_material_field_count
            != BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_STATEMENT_MATERIAL_FIELD_COUNT_V1
        || profile.claim_version != BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_CLAIM_VERSION_V1
        || profile.claim_field_count != BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_CLAIM_FIELD_COUNT_V1
        || profile.witness_digest_material_version
            != BFV_FULL_BOOTSTRAP_EXECUTION_WITNESS_DIGEST_MATERIAL_VERSION_V1
        || profile.witness_digest_material_field_count
            != BFV_FULL_BOOTSTRAP_EXECUTION_WITNESS_DIGEST_MATERIAL_FIELD_COUNT_V1
        || profile.witness_trace_field_count
            != BFV_FULL_BOOTSTRAP_EXECUTION_PREFIX_TRACE_FIELD_COUNT_V1
        || profile.witness_trace_bounds_field_count
            != BFV_FULL_BOOTSTRAP_EXECUTION_PREFIX_TRACE_BOUNDS_FIELD_COUNT_V1
        || profile.public_input_hash_count
            != BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_PUBLIC_INPUT_HASH_COUNT_V1
        || profile.public_input_hash_bytes
            != BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_PUBLIC_INPUT_HASH_BYTES_V1
    {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit proof profile public-input layout mismatch"
                .to_owned(),
        ));
    }
    if !profile.supports_exact_residual_multiple || !profile.supports_bounded_noise {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit proof profile must support exact and bounded-noise claims"
                .to_owned(),
        ));
    }
    Ok(())
}

fn validate_bfv_full_bootstrap_release_audit_key_evidence_shape_v1(
    label: &str,
    expected_role: BfvFullBootstrapCircuitArtifactRoleV1,
    evidence: &BfvFullBootstrapReleaseAuditKeyEvidenceV1,
) -> Result<(), BfvError> {
    if evidence.version != BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_KEY_EVIDENCE_VERSION_V1 {
        return Err(BfvError::InvalidParameters(format!(
            "{label} release audit key evidence version {} does not match canonical version {}",
            evidence.version, BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_KEY_EVIDENCE_VERSION_V1
        )));
    }
    if evidence.field_count != BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_KEY_EVIDENCE_FIELD_COUNT_V1 {
        return Err(BfvError::InvalidParameters(format!(
            "{label} release audit key evidence field count {} does not match canonical count {}",
            evidence.field_count, BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_KEY_EVIDENCE_FIELD_COUNT_V1
        )));
    }
    if evidence.key_role != expected_role {
        return Err(BfvError::InvalidParameters(format!(
            "{label} release audit key evidence role {:?} does not match expected role {:?}",
            evidence.key_role, expected_role
        )));
    }
    validate_bfv_full_bootstrap_digest_material_hashes(
        &format!("{label} release audit key evidence"),
        &[
            ("key digest", &evidence.key_digest),
            ("key material commitment", &evidence.key_material_commitment),
        ],
    )?;
    validate_bfv_full_bootstrap_native_payload_circuit_id(
        &format!("{label} release audit native payload circuit id"),
        &evidence.native_payload_circuit_id,
    )?;
    validate_nonzero_material_digest(
        &format!("{label} release audit native circuit fingerprint"),
        &evidence.native_circuit_fingerprint,
    )?;
    let expected_native_circuit_fingerprint =
        bfv_full_bootstrap_native_proof_circuit_fingerprint_v1(
            &evidence.native_payload_circuit_id,
        )?;
    if evidence.native_circuit_fingerprint != expected_native_circuit_fingerprint {
        return Err(BfvError::InvalidParameters(format!(
            "{label} release audit native circuit fingerprint mismatch"
        )));
    }
    validate_nonzero_sha256_digest(
        &format!("{label} release audit native payload digest"),
        &evidence.native_payload_digest,
    )?;
    validate_no_bfv_full_bootstrap_inert_sha256_digest(
        &format!("{label} release audit native payload digest"),
        &evidence.native_payload_digest,
    )?;
    let expected_payload_kind = match expected_role {
        BfvFullBootstrapCircuitArtifactRoleV1::ProverKey => {
            BFV_FULL_BOOTSTRAP_NATIVE_PROVER_PAYLOAD_KIND_V1
        }
        BfvFullBootstrapCircuitArtifactRoleV1::VerifierKey => {
            BFV_FULL_BOOTSTRAP_NATIVE_VERIFIER_PAYLOAD_KIND_V1
        }
        _ => {
            return Err(BfvError::InvalidParameters(format!(
                "{label} release audit key evidence role is not a proof-key role"
            )));
        }
    };
    if evidence.native_payload_kind != expected_payload_kind {
        return Err(BfvError::InvalidParameters(format!(
            "{label} release audit native payload kind mismatch"
        )));
    }
    Ok(())
}

fn hash_bfv_full_bootstrap_circuit_artifact_bundle_digest_material_v1(
    digest_material: &BfvFullBootstrapCircuitArtifactBundleDigestMaterialV1,
) -> Result<Hash, BfvError> {
    validate_bfv_full_bootstrap_circuit_artifact_bundle_digest_material_v1(digest_material)?;
    let bytes = norito::to_bytes(digest_material).map_err(|err| {
        BfvError::InvalidParameters(format!(
            "BFV full-bootstrap circuit artifact bundle digest material encoding failed: {err}"
        ))
    })?;
    Ok(Hash::new_from_chunks(&[
        BFV_FULL_BOOTSTRAP_CIRCUIT_ARTIFACT_BUNDLE_DIGEST_DOMAIN,
        bytes.as_slice(),
    ]))
}

fn validate_bfv_full_bootstrap_circuit_artifact_bundle_digest_material_v1(
    digest_material: &BfvFullBootstrapCircuitArtifactBundleDigestMaterialV1,
) -> Result<(), BfvError> {
    if digest_material.version
        != BFV_FULL_BOOTSTRAP_CIRCUIT_ARTIFACT_BUNDLE_DIGEST_MATERIAL_VERSION_V1
    {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap circuit artifact bundle digest material version {} does not match canonical version {}",
            digest_material.version,
            BFV_FULL_BOOTSTRAP_CIRCUIT_ARTIFACT_BUNDLE_DIGEST_MATERIAL_VERSION_V1
        )));
    }
    if digest_material.artifact_digest_count
        != BFV_FULL_BOOTSTRAP_CIRCUIT_ARTIFACT_BUNDLE_DIGEST_MATERIAL_ARTIFACT_DIGEST_COUNT_V1
    {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap circuit artifact bundle digest material artifact count {} does not match canonical count {}",
            digest_material.artifact_digest_count,
            BFV_FULL_BOOTSTRAP_CIRCUIT_ARTIFACT_BUNDLE_DIGEST_MATERIAL_ARTIFACT_DIGEST_COUNT_V1
        )));
    }
    validate_bfv_full_bootstrap_digest_material_hashes(
        "BFV full-bootstrap circuit artifact bundle digest material",
        &[
            (
                "coefficient-to-slot key digest",
                &digest_material.coefficient_to_slot_key_digest,
            ),
            (
                "slot-to-coefficient key digest",
                &digest_material.slot_to_coefficient_key_digest,
            ),
            (
                "blind-rotation key digest",
                &digest_material.blind_rotation_key_digest,
            ),
            (
                "sample-extraction key digest",
                &digest_material.sample_extraction_key_digest,
            ),
            ("accumulator digest", &digest_material.accumulator_digest),
            (
                "proof public-input schema digest",
                &digest_material.proof_public_input_schema_digest,
            ),
            (
                "arithmetic AIR constraint-system artifact digest",
                &digest_material.arithmetic_air_constraint_system_artifact_digest,
            ),
            ("prover-key digest", &digest_material.prover_key_digest),
            ("verifier-key digest", &digest_material.verifier_key_digest),
        ],
    )
}

/// Build typed proof input material for a dedicated BFV full-bootstrap material prover.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set, public key, evaluation-key
/// bundle, concrete artifact bundle, or derived statement hash fails validation.
pub fn bfv_full_bootstrap_material_proof_input_material_v1(
    params: &BfvParameters,
    public_key: &BfvPublicKey,
    evaluation_keys: &BfvEvaluationKeyBundle,
    artifact_bundle: &BfvFullBootstrapCircuitArtifactBundleV1,
) -> Result<BfvFullBootstrapMaterialProofInputMaterialV1, BfvError> {
    let statement_hash = evaluation_keys
        .full_bootstrap_material_proof_statement_digest(params, public_key)?
        .ok_or_else(|| {
            BfvError::InvalidParameters(
                "BFV full-bootstrap material proof input requires governed FullBootstrapV1 material"
                    .to_owned(),
            )
        })?;
    let material = BfvFullBootstrapMaterialProofInputMaterialV1 {
        version: BFV_FULL_BOOTSTRAP_MATERIAL_PROOF_INPUT_MATERIAL_VERSION_V1,
        field_count: BFV_FULL_BOOTSTRAP_MATERIAL_PROOF_INPUT_MATERIAL_FIELD_COUNT_V1,
        params: *params,
        public_key: public_key.clone(),
        evaluation_keys: evaluation_keys.clone(),
        artifact_bundle: artifact_bundle.clone(),
        statement_hash,
    };
    validate_bfv_full_bootstrap_material_proof_input_material_v1(&material)?;
    Ok(material)
}

/// Validate typed proof input material for a dedicated BFV full-bootstrap material prover.
///
/// # Errors
/// Returns [`BfvError`] when layout metadata is stale, the embedded public key
/// or evaluation-key bundle is invalid, the bundle is not governed
/// `FullBootstrapV1` material, the concrete artifact bundle does not match the
/// governed material commitments, or the statement hash is not the canonical
/// hash derived from the embedded material.
pub fn validate_bfv_full_bootstrap_material_proof_input_material_v1(
    material: &BfvFullBootstrapMaterialProofInputMaterialV1,
) -> Result<(), BfvError> {
    if material.version != BFV_FULL_BOOTSTRAP_MATERIAL_PROOF_INPUT_MATERIAL_VERSION_V1 {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap material proof input material version {} does not match canonical version {}",
            material.version, BFV_FULL_BOOTSTRAP_MATERIAL_PROOF_INPUT_MATERIAL_VERSION_V1
        )));
    }
    if material.field_count != BFV_FULL_BOOTSTRAP_MATERIAL_PROOF_INPUT_MATERIAL_FIELD_COUNT_V1 {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap material proof input material field count {} does not match canonical count {}",
            material.field_count, BFV_FULL_BOOTSTRAP_MATERIAL_PROOF_INPUT_MATERIAL_FIELD_COUNT_V1
        )));
    }
    validate_nonzero_material_digest(
        "BFV full-bootstrap material proof input statement hash",
        &material.statement_hash,
    )?;
    validate_no_full_bootstrap_placeholder_material_digest(
        "BFV full-bootstrap material proof input statement hash",
        &material.statement_hash,
    )?;
    let expected_statement_hash = material
        .evaluation_keys
        .full_bootstrap_material_proof_statement_digest(&material.params, &material.public_key)?
        .ok_or_else(|| {
            BfvError::InvalidParameters(
                "BFV full-bootstrap material proof input requires governed FullBootstrapV1 material"
                    .to_owned(),
            )
        })?;
    if material.statement_hash != expected_statement_hash {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap material proof input material statement hash mismatch".to_owned(),
        ));
    }
    let governed_material = material
        .evaluation_keys
        .bootstrap_key
        .as_ref()
        .and_then(|bootstrap_key| bootstrap_key.full_bootstrap_material.as_ref())
        .ok_or_else(|| {
            BfvError::InvalidParameters(
                "BFV full-bootstrap material proof input requires governed FullBootstrapV1 material"
                    .to_owned(),
            )
        })?;
    validate_bfv_full_bootstrap_circuit_artifact_bundle_v1(
        &material.params,
        governed_material,
        &material.artifact_bundle,
    )
    .map_err(|err| {
        BfvError::InvalidParameters(format!(
            "BFV full-bootstrap material proof input artifact bundle failed validation: {err}"
        ))
    })?;
    Ok(())
}

/// Validate material proof input material against caller-owned governed artifacts.
///
/// This companion validates the self-contained package, then reconstructs the
/// exact package from the caller's parameter set, public key, evaluation-key
/// bundle, and concrete artifact bundle before accepting it.
///
/// # Errors
/// Returns [`BfvError`] when the supplied material is malformed or does not
/// match the canonical package derived from the caller-owned inputs.
pub fn validate_bfv_full_bootstrap_material_proof_input_material_for_artifacts_v1(
    params: &BfvParameters,
    public_key: &BfvPublicKey,
    evaluation_keys: &BfvEvaluationKeyBundle,
    artifact_bundle: &BfvFullBootstrapCircuitArtifactBundleV1,
    material: &BfvFullBootstrapMaterialProofInputMaterialV1,
) -> Result<(), BfvError> {
    validate_bfv_full_bootstrap_material_proof_input_material_v1(material)?;
    let expected_material = bfv_full_bootstrap_material_proof_input_material_v1(
        params,
        public_key,
        evaluation_keys,
        artifact_bundle,
    )?;
    if material != &expected_material {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap material proof input material does not match caller artifacts"
                .to_owned(),
        ));
    }
    Ok(())
}

/// Hash self-contained typed proof input material for a BFV full-bootstrap material proof.
///
/// Prefer [`bfv_full_bootstrap_material_proof_input_material_digest_for_artifacts_v1`]
/// when the caller-owned parameter set, public key, evaluation keys, and
/// artifacts are available.
///
/// # Errors
/// Returns [`BfvError`] when material proof input validation or canonical Norito
/// encoding fails.
pub fn bfv_full_bootstrap_material_proof_input_material_digest_v1(
    material: &BfvFullBootstrapMaterialProofInputMaterialV1,
) -> Result<Hash, BfvError> {
    validate_bfv_full_bootstrap_material_proof_input_material_v1(material)?;
    let bytes = norito::to_bytes(material).map_err(|err| {
        BfvError::InvalidParameters(format!(
            "BFV full-bootstrap material proof input material encoding failed: {err}"
        ))
    })?;
    Ok(Hash::new_from_chunks(&[
        BFV_FULL_BOOTSTRAP_MATERIAL_PROOF_INPUT_MATERIAL_DIGEST_DOMAIN,
        bytes.as_slice(),
    ]))
}

/// Hash material proof input material after matching it to caller-owned artifacts.
///
/// # Errors
/// Returns [`BfvError`] when caller-bound material proof input validation or
/// canonical Norito encoding fails.
pub fn bfv_full_bootstrap_material_proof_input_material_digest_for_artifacts_v1(
    params: &BfvParameters,
    public_key: &BfvPublicKey,
    evaluation_keys: &BfvEvaluationKeyBundle,
    artifact_bundle: &BfvFullBootstrapCircuitArtifactBundleV1,
    material: &BfvFullBootstrapMaterialProofInputMaterialV1,
) -> Result<Hash, BfvError> {
    validate_bfv_full_bootstrap_material_proof_input_material_for_artifacts_v1(
        params,
        public_key,
        evaluation_keys,
        artifact_bundle,
        material,
    )?;
    bfv_full_bootstrap_material_proof_input_material_digest_v1(material)
}

/// Build typed deterministic witness material for a full-bootstrap claim.
///
/// The material is derived by executing the governed full-bootstrap prefix
/// through the exact or bounded-noise artifact-aware path and propagating the
/// matching public bound trace. The
/// `execution_witness_digest` field already present in `claim` is intentionally
/// ignored while deriving the expected witness material.
///
/// # Errors
/// Returns [`BfvError`] when the governed full-bootstrap trace cannot execute,
/// the claimed output ciphertext does not match the deterministic trace output,
/// or the claimed output bound does not match the deterministic bound trace.
pub fn bfv_full_bootstrap_execution_witness_digest_material_v1(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    artifacts: &BfvFullBootstrapCircuitArtifactBundleV1,
    galois_keys: &[BfvGaloisKey],
    claim: &BfvFullBootstrapExecutionProofClaimV1,
) -> Result<BfvFullBootstrapExecutionWitnessDigestMaterialV1, BfvError> {
    if usize::try_from(claim.slot_index).map_or(true, |slot_index| slot_index >= params.degree()) {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap execution witness slot index exceeds parameter slot capacity"
                .to_owned(),
        ));
    }
    validate_ciphertext(params, &claim.input_ciphertext)?;
    validate_ciphertext_not_all_zero(
        "BFV full-bootstrap execution witness input ciphertext",
        &claim.input_ciphertext,
    )?;
    validate_ciphertext(params, &claim.output_ciphertext)?;
    validate_ciphertext_not_all_zero(
        "BFV full-bootstrap execution witness output ciphertext",
        &claim.output_ciphertext,
    )?;
    let (trace, trace_bounds) = match claim.bound_mode {
        BfvFullBootstrapExecutionProofBoundModeV1::ExactResidualMultiple => {
            let trace = apply_bfv_full_bootstrap_execution_prefix_trace_registered_rns_exact_v1(
                params,
                bootstrap_key,
                artifacts,
                galois_keys,
                &claim.input_ciphertext,
            )?;
            let trace_bounds =
                bfv_full_bootstrap_execution_prefix_trace_output_residual_multiple_bounds_v1(
                    params,
                    bootstrap_key,
                    artifacts,
                    galois_keys,
                    claim.input_bound,
                )?;
            (trace, trace_bounds)
        }
        BfvFullBootstrapExecutionProofBoundModeV1::BoundedNoise => {
            let trace =
                apply_bfv_full_bootstrap_execution_prefix_trace_bounded_noise_registered_rns_basis_extension_exact_v1(
                    params,
                    bootstrap_key,
                    artifacts,
                    galois_keys,
                    &claim.input_ciphertext,
                )?;
            let trace_bounds =
                bfv_full_bootstrap_execution_prefix_trace_bounded_noise_output_bounds_v1(
                    params,
                    bootstrap_key,
                    artifacts,
                    galois_keys,
                    claim.input_bound,
                )?;
            (trace, trace_bounds)
        }
    };
    if trace.slot_to_coefficient_output != claim.output_ciphertext {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap execution witness output ciphertext does not match deterministic governed trace"
                .to_owned(),
        ));
    }
    if trace_bounds.slot_to_coefficient != claim.output_bound {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap execution witness output bound {} does not match deterministic governed bound {}",
            claim.output_bound, trace_bounds.slot_to_coefficient
        )));
    }
    let material = full_bootstrap_material_from_key(bootstrap_key)?;
    let full_bootstrap_material_digest =
        bfv_full_bootstrap_circuit_material_digest(params, material)?;
    let artifact_bundle_digest =
        bfv_full_bootstrap_circuit_artifact_bundle_digest(params, material, artifacts)?;
    let galois_key_set_digest = bfv_full_bootstrap_galois_key_set_digest_v1(params, galois_keys)?;
    Ok(BfvFullBootstrapExecutionWitnessDigestMaterialV1 {
        version: BFV_FULL_BOOTSTRAP_EXECUTION_WITNESS_DIGEST_MATERIAL_VERSION_V1,
        field_count: BFV_FULL_BOOTSTRAP_EXECUTION_WITNESS_DIGEST_MATERIAL_FIELD_COUNT_V1,
        params: *params,
        bootstrap_key: bootstrap_key.clone(),
        full_bootstrap_material_digest,
        artifact_bundle_digest,
        galois_key_set_digest,
        bound_mode: claim.bound_mode,
        slot_index: claim.slot_index,
        input_ciphertext: claim.input_ciphertext.clone(),
        output_ciphertext: claim.output_ciphertext.clone(),
        input_bound: claim.input_bound,
        output_bound: claim.output_bound,
        trace,
        trace_bounds,
    })
}

/// Validate typed deterministic witness material for one full-bootstrap claim.
///
/// This is the public admission companion to
/// [`bfv_full_bootstrap_execution_witness_digest_material_v1`]. It validates the
/// self-describing witness layout, governed full-bootstrap key/material
/// digests, Galois-key-set digest, ciphertext shapes, public bound model,
/// trace shape, and final trace-to-claim output binding before a
/// prover/verifier hashes externally held witness material.
///
/// # Errors
/// Returns [`BfvError`] when witness metadata is stale, malformed, or internally
/// inconsistent.
#[allow(clippy::too_many_lines)]
pub fn validate_bfv_full_bootstrap_execution_witness_digest_material_v1(
    material: &BfvFullBootstrapExecutionWitnessDigestMaterialV1,
) -> Result<(), BfvError> {
    if material.version != BFV_FULL_BOOTSTRAP_EXECUTION_WITNESS_DIGEST_MATERIAL_VERSION_V1 {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap execution witness material version {} does not match canonical version {}",
            material.version, BFV_FULL_BOOTSTRAP_EXECUTION_WITNESS_DIGEST_MATERIAL_VERSION_V1
        )));
    }
    if material.field_count != BFV_FULL_BOOTSTRAP_EXECUTION_WITNESS_DIGEST_MATERIAL_FIELD_COUNT_V1 {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap execution witness material field count {} does not match canonical count {}",
            material.field_count,
            BFV_FULL_BOOTSTRAP_EXECUTION_WITNESS_DIGEST_MATERIAL_FIELD_COUNT_V1
        )));
    }
    let params = &material.params;
    validate_bfv_full_bootstrap_key_execution_preflight_v1(params, &material.bootstrap_key)?;
    let full_bootstrap_material = full_bootstrap_material_from_key(&material.bootstrap_key)?;
    let expected_material_digest =
        bfv_full_bootstrap_circuit_material_digest(params, full_bootstrap_material)?;
    if material.full_bootstrap_material_digest != expected_material_digest {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap execution witness material digest mismatch".to_owned(),
        ));
    }
    validate_nonzero_material_digest(
        "BFV full-bootstrap execution witness artifact bundle digest",
        &material.artifact_bundle_digest,
    )?;
    let expected_artifact_bundle_digest =
        bfv_full_bootstrap_circuit_artifact_bundle_digest_from_material_v1(
            params,
            full_bootstrap_material,
        )?;
    if material.artifact_bundle_digest != expected_artifact_bundle_digest {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap execution witness artifact bundle digest mismatch".to_owned(),
        ));
    }
    validate_nonzero_material_digest(
        "BFV full-bootstrap execution witness Galois key set digest",
        &material.galois_key_set_digest,
    )?;
    validate_no_full_bootstrap_placeholder_material_digest(
        "BFV full-bootstrap execution witness Galois key set digest",
        &material.galois_key_set_digest,
    )?;
    validate_bfv_full_bootstrap_digest_material_hashes(
        "BFV full-bootstrap execution witness digest material",
        &[
            (
                "full-bootstrap material digest",
                &material.full_bootstrap_material_digest,
            ),
            ("artifact bundle digest", &material.artifact_bundle_digest),
            ("Galois key set digest", &material.galois_key_set_digest),
        ],
    )?;
    if usize::try_from(material.slot_index).map_or(true, |slot_index| slot_index >= params.degree())
    {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap execution witness slot index exceeds parameter slot capacity"
                .to_owned(),
        ));
    }
    validate_ciphertext(params, &material.input_ciphertext)?;
    validate_ciphertext_not_all_zero(
        "BFV full-bootstrap execution witness material input ciphertext",
        &material.input_ciphertext,
    )?;
    validate_ciphertext(params, &material.output_ciphertext)?;
    validate_ciphertext_not_all_zero(
        "BFV full-bootstrap execution witness material output ciphertext",
        &material.output_ciphertext,
    )?;
    validate_bfv_full_bootstrap_execution_prefix_trace_v1(params, &material.trace)?;
    validate_bfv_full_bootstrap_execution_prefix_trace_bounds_v1(
        params,
        material.bound_mode,
        &material.trace_bounds,
    )?;
    validate_bfv_full_bootstrap_execution_witness_claim_bounds_v1(
        params,
        material.bound_mode,
        material.input_bound,
        material.output_bound,
    )?;
    let sample_extraction = bfv_full_bootstrap_sample_extraction_from_raw_sample_v1(
        params,
        &material.trace.raw_extracted_sample,
    )?;
    let expected_raw_extracted_sample = match material.bound_mode {
        BfvFullBootstrapExecutionProofBoundModeV1::ExactResidualMultiple => {
            apply_bfv_full_bootstrap_sample_extraction_raw_lwe_v1(
                params,
                &material.trace.blind_rotation_output,
                sample_extraction,
            )?
        }
        BfvFullBootstrapExecutionProofBoundModeV1::BoundedNoise => {
            apply_bfv_full_bootstrap_sample_extraction_bounded_noise_raw_lwe_v1(
                params,
                &material.trace.blind_rotation_output,
                sample_extraction,
            )?
        }
    };
    if material.trace.raw_extracted_sample != expected_raw_extracted_sample {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap execution witness raw extracted sample does not match blind-rotation output"
                .to_owned(),
        ));
    }
    let expected_raw_extracted_sample_bound = match material.bound_mode {
        BfvFullBootstrapExecutionProofBoundModeV1::ExactResidualMultiple => {
            bfv_full_bootstrap_raw_sample_extraction_output_residual_multiple_bound_v1(
                params,
                sample_extraction,
                material.trace_bounds.blind_rotation,
            )?
        }
        BfvFullBootstrapExecutionProofBoundModeV1::BoundedNoise => {
            bfv_full_bootstrap_raw_sample_extraction_bounded_noise_output_bound_v1(
                params,
                sample_extraction,
                material.trace_bounds.blind_rotation,
            )?
        }
    };
    if material.trace_bounds.raw_extracted_sample != expected_raw_extracted_sample_bound {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap execution witness raw extracted sample bound {} does not match blind-rotation bound {}",
            material.trace_bounds.raw_extracted_sample, expected_raw_extracted_sample_bound
        )));
    }
    let expected_coefficient_zero_repack_output = match material.bound_mode {
        BfvFullBootstrapExecutionProofBoundModeV1::ExactResidualMultiple => {
            repack_bfv_full_bootstrap_raw_sample_as_coefficient_zero_ciphertext_v1(
                params,
                &material.trace.raw_extracted_sample,
            )?
        }
        BfvFullBootstrapExecutionProofBoundModeV1::BoundedNoise => {
            repack_bfv_full_bootstrap_raw_sample_as_bounded_noise_coefficient_zero_ciphertext_v1(
                params,
                &material.trace.raw_extracted_sample,
            )?
        }
    };
    if material.trace.coefficient_zero_repack_output != expected_coefficient_zero_repack_output {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap execution witness coefficient-zero repack output does not match raw extracted sample"
                .to_owned(),
        ));
    }
    let expected_coefficient_zero_repack_bound = match material.bound_mode {
        BfvFullBootstrapExecutionProofBoundModeV1::ExactResidualMultiple => {
            bfv_full_bootstrap_raw_sample_coefficient_zero_repack_residual_bound_from_raw_sample_bound_v1(
                params,
                material.trace_bounds.raw_extracted_sample,
            )?
        }
        BfvFullBootstrapExecutionProofBoundModeV1::BoundedNoise => {
            bfv_full_bootstrap_raw_sample_coefficient_zero_repack_bounded_noise_bound_from_raw_sample_bound_v1(
                params,
                material.trace_bounds.raw_extracted_sample,
            )?
        }
    };
    if material.trace_bounds.coefficient_zero_repack != expected_coefficient_zero_repack_bound {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap execution witness coefficient-zero repack bound {} does not match raw sample bound {}",
            material.trace_bounds.coefficient_zero_repack, expected_coefficient_zero_repack_bound
        )));
    }
    let expected_sample_switch_bound = match material.bound_mode {
        BfvFullBootstrapExecutionProofBoundModeV1::ExactResidualMultiple => {
            bfv_full_bootstrap_sample_extraction_switch_key_output_residual_multiple_bound_from_raw_sample_bound_v1(
                params,
                material.trace_bounds.raw_extracted_sample,
            )?
        }
        BfvFullBootstrapExecutionProofBoundModeV1::BoundedNoise => {
            bfv_full_bootstrap_sample_extraction_switch_key_bounded_noise_output_bound_from_raw_sample_bound_v1(
                params,
                material.trace_bounds.raw_extracted_sample,
            )?
        }
    };
    if material.trace_bounds.sample_switch != expected_sample_switch_bound {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap execution witness sample-switch bound {} does not match raw sample bound {}",
            material.trace_bounds.sample_switch, expected_sample_switch_bound
        )));
    }
    if material.trace.slot_to_coefficient_output != material.output_ciphertext {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap execution witness trace output ciphertext does not match witness output ciphertext"
                .to_owned(),
        ));
    }
    if material.trace_bounds.slot_to_coefficient != material.output_bound {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap execution witness trace output bound {} does not match witness output bound {}",
            material.trace_bounds.slot_to_coefficient, material.output_bound
        )));
    }
    Ok(())
}

/// Validate deterministic witness material against concrete governed artifacts.
///
/// This artifact-aware companion recomputes the full-bootstrap prefix trace
/// from the supplied `FullBootstrapV1` key, artifact bundle, and Galois keys.
/// Use it whenever externally held witness material is available together with
/// the concrete release artifacts; the plain witness-material validator can
/// only check self-consistency, the declared Galois-key-set digest, and final
/// trace-to-claim bindings.
///
/// # Errors
/// Returns [`BfvError`] when the witness material is malformed, is bound to a
/// different parameter set or bootstrap key, or does not match the
/// deterministic trace derived from the governed artifacts.
pub fn validate_bfv_full_bootstrap_execution_witness_digest_material_for_artifacts_v1(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    artifacts: &BfvFullBootstrapCircuitArtifactBundleV1,
    galois_keys: &[BfvGaloisKey],
    material: &BfvFullBootstrapExecutionWitnessDigestMaterialV1,
) -> Result<(), BfvError> {
    validate_bfv_full_bootstrap_execution_witness_digest_material_v1(material)?;
    if material.params != *params {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap execution witness material parameter set mismatch".to_owned(),
        ));
    }
    if material.bootstrap_key != *bootstrap_key {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap execution witness material bootstrap key mismatch".to_owned(),
        ));
    }
    let expected_galois_key_set_digest =
        bfv_full_bootstrap_galois_key_set_digest_v1(params, galois_keys)?;
    if material.galois_key_set_digest != expected_galois_key_set_digest {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap execution witness Galois key set digest mismatch".to_owned(),
        ));
    }
    let claim = bfv_full_bootstrap_execution_proof_claim_from_witness_material_v1(material)?;
    let expected_material = bfv_full_bootstrap_execution_witness_digest_material_v1(
        params,
        bootstrap_key,
        artifacts,
        galois_keys,
        &claim,
    )?;
    if material != &expected_material {
        let mismatch = bfv_full_bootstrap_execution_witness_artifact_mismatch_label_v1(
            material,
            &expected_material,
        );
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap execution witness material {mismatch} does not match governed artifact trace"
        )));
    }
    Ok(())
}

fn bfv_full_bootstrap_execution_witness_artifact_mismatch_label_v1(
    material: &BfvFullBootstrapExecutionWitnessDigestMaterialV1,
    expected: &BfvFullBootstrapExecutionWitnessDigestMaterialV1,
) -> &'static str {
    if material.full_bootstrap_material_digest != expected.full_bootstrap_material_digest {
        return "full-bootstrap material digest";
    }
    if material.artifact_bundle_digest != expected.artifact_bundle_digest {
        return "artifact bundle digest";
    }
    if material.galois_key_set_digest != expected.galois_key_set_digest {
        return "Galois key set digest";
    }
    if material.trace.coefficient_to_slot_output != expected.trace.coefficient_to_slot_output {
        return "coefficient-to-slot output";
    }
    if material.trace.blind_rotation_output != expected.trace.blind_rotation_output {
        return "blind-rotation output";
    }
    if material.trace.raw_extracted_sample != expected.trace.raw_extracted_sample {
        return "raw extracted sample";
    }
    if material.trace.coefficient_zero_repack_output
        != expected.trace.coefficient_zero_repack_output
    {
        return "coefficient-zero repack output";
    }
    if material.trace.diagnostic_slot_to_coefficient_output
        != expected.trace.diagnostic_slot_to_coefficient_output
    {
        return "diagnostic slot-to-coefficient output";
    }
    if material.trace.sample_switch_output != expected.trace.sample_switch_output {
        return "sample-switch output";
    }
    if material.trace.slot_to_coefficient_output != expected.trace.slot_to_coefficient_output {
        return "slot-to-coefficient output";
    }
    if material.trace_bounds.coefficient_to_slot != expected.trace_bounds.coefficient_to_slot {
        return "coefficient-to-slot bound";
    }
    if material.trace_bounds.blind_rotation != expected.trace_bounds.blind_rotation {
        return "blind-rotation bound";
    }
    if material.trace_bounds.raw_extracted_sample != expected.trace_bounds.raw_extracted_sample {
        return "raw extracted sample bound";
    }
    if material.trace_bounds.coefficient_zero_repack
        != expected.trace_bounds.coefficient_zero_repack
    {
        return "coefficient-zero repack bound";
    }
    if material.trace_bounds.sample_switch != expected.trace_bounds.sample_switch {
        return "sample-switch bound";
    }
    if material.trace_bounds.slot_to_coefficient != expected.trace_bounds.slot_to_coefficient {
        return "slot-to-coefficient bound";
    }
    "typed material"
}

fn bfv_full_bootstrap_sample_extraction_from_raw_sample_v1(
    params: &BfvParameters,
    sample: &BfvFullBootstrapRawExtractedSampleV1,
) -> Result<BfvFullBootstrapSampleExtractionV1, BfvError> {
    let source_slot_count = u16::try_from(params.degree()).map_err(|_| {
        BfvError::InvalidParameters(
            "BFV full-bootstrap execution witness sample extraction degree exceeds u16 slot metadata"
                .to_owned(),
        )
    })?;
    let sample_extraction = BfvFullBootstrapSampleExtractionV1 {
        source_slot_count,
        source_ciphertext_component_count: BFV_FULL_BOOTSTRAP_CIPHERTEXT_COMPONENT_COUNT_V1,
        extracted_coefficient_index: sample.source_coefficient_index,
        output_ciphertext_component_count: BFV_FULL_BOOTSTRAP_CIPHERTEXT_COMPONENT_COUNT_V1,
    };
    validate_bfv_full_bootstrap_sample_extraction_v1(params, sample_extraction)?;
    Ok(sample_extraction)
}

fn validate_bfv_full_bootstrap_execution_prefix_trace_v1(
    params: &BfvParameters,
    trace: &BfvFullBootstrapExecutionPrefixTraceV1,
) -> Result<(), BfvError> {
    for (label, ciphertext) in [
        (
            "BFV full-bootstrap execution trace coefficient-to-slot output",
            &trace.coefficient_to_slot_output,
        ),
        (
            "BFV full-bootstrap execution trace blind-rotation output",
            &trace.blind_rotation_output,
        ),
        (
            "BFV full-bootstrap execution trace coefficient-zero repack output",
            &trace.coefficient_zero_repack_output,
        ),
        (
            "BFV full-bootstrap execution trace diagnostic slot-to-coefficient output",
            &trace.diagnostic_slot_to_coefficient_output,
        ),
        (
            "BFV full-bootstrap execution trace sample-switch output",
            &trace.sample_switch_output,
        ),
        (
            "BFV full-bootstrap execution trace slot-to-coefficient output",
            &trace.slot_to_coefficient_output,
        ),
    ] {
        validate_ciphertext(params, ciphertext)?;
        validate_ciphertext_not_all_zero(label, ciphertext)?;
    }
    validate_bfv_full_bootstrap_raw_extracted_sample_v1(params, &trace.raw_extracted_sample)?;
    Ok(())
}

fn validate_bfv_full_bootstrap_execution_prefix_trace_bounds_v1(
    params: &BfvParameters,
    bound_mode: BfvFullBootstrapExecutionProofBoundModeV1,
    bounds: &BfvFullBootstrapExecutionPrefixTraceBoundsV1,
) -> Result<(), BfvError> {
    match bound_mode {
        BfvFullBootstrapExecutionProofBoundModeV1::ExactResidualMultiple => {
            for (label, bound) in [
                (
                    "BFV full-bootstrap execution witness coefficient-to-slot residual bound",
                    bounds.coefficient_to_slot,
                ),
                (
                    "BFV full-bootstrap execution witness blind-rotation residual bound",
                    bounds.blind_rotation,
                ),
                (
                    "BFV full-bootstrap execution witness raw-sample residual bound",
                    bounds.raw_extracted_sample,
                ),
                (
                    "BFV full-bootstrap execution witness coefficient-zero residual bound",
                    bounds.coefficient_zero_repack,
                ),
                (
                    "BFV full-bootstrap execution witness sample-switch residual bound",
                    bounds.sample_switch,
                ),
                (
                    "BFV full-bootstrap execution witness slot-to-coefficient residual bound",
                    bounds.slot_to_coefficient,
                ),
            ] {
                validate_exact_residual_bound_within_centered_capacity(params, bound, label)?;
            }
        }
        BfvFullBootstrapExecutionProofBoundModeV1::BoundedNoise => {
            validate_bfv_bounded_noise_encryption_capacity(params)?;
            for (label, bound) in [
                (
                    "BFV full-bootstrap execution witness coefficient-to-slot bounded-noise bound",
                    bounds.coefficient_to_slot,
                ),
                (
                    "BFV full-bootstrap execution witness blind-rotation bounded-noise bound",
                    bounds.blind_rotation,
                ),
                (
                    "BFV full-bootstrap execution witness raw-sample bounded-noise bound",
                    bounds.raw_extracted_sample,
                ),
                (
                    "BFV full-bootstrap execution witness coefficient-zero bounded-noise bound",
                    bounds.coefficient_zero_repack,
                ),
                (
                    "BFV full-bootstrap execution witness sample-switch bounded-noise bound",
                    bounds.sample_switch,
                ),
                (
                    "BFV full-bootstrap execution witness slot-to-coefficient bounded-noise bound",
                    bounds.slot_to_coefficient,
                ),
            ] {
                validate_bounded_noise_bound_within_decoding_capacity(params, bound, label)?;
            }
        }
    }
    Ok(())
}

fn validate_bfv_full_bootstrap_execution_witness_claim_bounds_v1(
    params: &BfvParameters,
    bound_mode: BfvFullBootstrapExecutionProofBoundModeV1,
    input_bound: u128,
    output_bound: u128,
) -> Result<(), BfvError> {
    match bound_mode {
        BfvFullBootstrapExecutionProofBoundModeV1::ExactResidualMultiple => {
            validate_exact_residual_bound_within_centered_capacity(
                params,
                input_bound,
                "BFV full-bootstrap execution witness input residual bound",
            )?;
            validate_exact_residual_bound_within_centered_capacity(
                params,
                output_bound,
                "BFV full-bootstrap execution witness output residual bound",
            )
        }
        BfvFullBootstrapExecutionProofBoundModeV1::BoundedNoise => {
            validate_bfv_bounded_noise_encryption_capacity(params)?;
            validate_bounded_noise_bound_within_decoding_capacity(
                params,
                input_bound,
                "BFV full-bootstrap execution witness input bounded-noise bound",
            )?;
            validate_bounded_noise_bound_within_decoding_capacity(
                params,
                output_bound,
                "BFV full-bootstrap execution witness output bounded-noise bound",
            )
        }
    }
}

/// Hash self-consistent externally held typed deterministic witness material.
///
/// Prefer [`bfv_full_bootstrap_execution_witness_digest_from_material_for_artifacts_v1`]
/// when the concrete governed artifacts and Galois keys are available.
///
/// # Errors
/// Returns [`BfvError`] when witness material validation or canonical Norito
/// encoding fails.
pub fn bfv_full_bootstrap_execution_witness_digest_from_material_v1(
    material: &BfvFullBootstrapExecutionWitnessDigestMaterialV1,
) -> Result<Hash, BfvError> {
    validate_bfv_full_bootstrap_execution_witness_digest_material_v1(material)?;
    let bytes = norito::to_bytes(material).map_err(|err| {
        BfvError::InvalidParameters(format!(
            "BFV full-bootstrap execution witness digest material encoding failed: {err}"
        ))
    })?;
    Ok(Hash::new_from_chunks(&[
        BFV_FULL_BOOTSTRAP_EXECUTION_WITNESS_DIGEST_DOMAIN,
        bytes.as_slice(),
    ]))
}

/// Hash externally held typed witness material after replaying it against artifacts.
///
/// # Errors
/// Returns [`BfvError`] when artifact-aware witness material validation or
/// canonical Norito encoding fails.
pub fn bfv_full_bootstrap_execution_witness_digest_from_material_for_artifacts_v1(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    artifacts: &BfvFullBootstrapCircuitArtifactBundleV1,
    galois_keys: &[BfvGaloisKey],
    material: &BfvFullBootstrapExecutionWitnessDigestMaterialV1,
) -> Result<Hash, BfvError> {
    validate_bfv_full_bootstrap_execution_witness_digest_material_for_artifacts_v1(
        params,
        bootstrap_key,
        artifacts,
        galois_keys,
        material,
    )?;
    bfv_full_bootstrap_execution_witness_digest_from_material_v1(material)
}

/// Return the deterministic arithmetic witness digest for a full-bootstrap claim.
///
/// The digest is the domain-separated hash of the typed governed witness
/// material. The `execution_witness_digest` field already present in `claim` is
/// intentionally ignored while deriving the expected digest.
///
/// # Errors
/// Returns [`BfvError`] when governed witness material cannot be derived or
/// canonical witness encoding fails.
pub fn bfv_full_bootstrap_execution_witness_digest_v1(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    artifacts: &BfvFullBootstrapCircuitArtifactBundleV1,
    galois_keys: &[BfvGaloisKey],
    claim: &BfvFullBootstrapExecutionProofClaimV1,
) -> Result<Hash, BfvError> {
    let digest_material = bfv_full_bootstrap_execution_witness_digest_material_v1(
        params,
        bootstrap_key,
        artifacts,
        galois_keys,
        claim,
    )?;
    bfv_full_bootstrap_execution_witness_digest_from_material_for_artifacts_v1(
        params,
        bootstrap_key,
        artifacts,
        galois_keys,
        &digest_material,
    )
}

/// Reconstruct the public execution proof claim from validated witness material.
///
/// # Errors
/// Returns [`BfvError`] when witness material validation or witness hashing
/// fails.
pub fn bfv_full_bootstrap_execution_proof_claim_from_witness_material_v1(
    material: &BfvFullBootstrapExecutionWitnessDigestMaterialV1,
) -> Result<BfvFullBootstrapExecutionProofClaimV1, BfvError> {
    let execution_witness_digest =
        bfv_full_bootstrap_execution_witness_digest_from_material_v1(material)?;
    Ok(BfvFullBootstrapExecutionProofClaimV1 {
        slot_index: material.slot_index,
        input_ciphertext: material.input_ciphertext.clone(),
        output_ciphertext: material.output_ciphertext.clone(),
        bound_mode: material.bound_mode,
        input_bound: material.input_bound,
        output_bound: material.output_bound,
        execution_witness_digest,
    })
}

/// Derive the canonical execution proof statement hash from typed witness material.
///
/// This is the external prover companion to
/// [`bfv_full_bootstrap_execution_proof_statement_digest_with_witness_v1`].
/// It does not require the original artifact bytes because the witness material
/// has already bound and validated the governed material and artifact-bundle
/// digests used by the statement.
///
/// # Errors
/// Returns [`BfvError`] when the public key or witness material is malformed,
/// or when canonical statement encoding fails.
pub fn bfv_full_bootstrap_execution_proof_statement_digest_from_witness_material_v1(
    public_key: &BfvPublicKey,
    witness_material: &BfvFullBootstrapExecutionWitnessDigestMaterialV1,
) -> Result<Hash, BfvError> {
    validate_public_key(&witness_material.params, public_key)?;
    validate_bootstrap_key_public_key_digest(
        &witness_material.params,
        public_key,
        &witness_material.bootstrap_key,
    )?;
    let claim =
        bfv_full_bootstrap_execution_proof_claim_from_witness_material_v1(witness_material)?;
    let statement = BfvFullBootstrapExecutionProofStatementMaterial {
        version: BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_STATEMENT_MATERIAL_VERSION_V1,
        field_count: BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_STATEMENT_MATERIAL_FIELD_COUNT_V1,
        params: witness_material.params,
        public_key: public_key.clone(),
        bootstrap_key: witness_material.bootstrap_key.clone(),
        full_bootstrap_material_digest: witness_material.full_bootstrap_material_digest,
        artifact_bundle_digest: witness_material.artifact_bundle_digest,
        claim,
    };
    let bytes = norito::to_bytes(&statement).map_err(|err| {
        BfvError::InvalidParameters(format!(
            "full-bootstrap execution proof statement encoding failed: {err}"
        ))
    })?;
    Ok(Hash::new_from_chunks(&[
        BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_STATEMENT_DOMAIN,
        bytes.as_slice(),
    ]))
}

/// Build typed proof input material for a dedicated BFV full-bootstrap prover.
///
/// # Errors
/// Returns [`BfvError`] when the public key, witness material, or derived
/// statement hash fails validation.
pub fn bfv_full_bootstrap_execution_proof_input_material_v1(
    public_key: &BfvPublicKey,
    witness_material: &BfvFullBootstrapExecutionWitnessDigestMaterialV1,
) -> Result<BfvFullBootstrapExecutionProofInputMaterialV1, BfvError> {
    let statement_hash =
        bfv_full_bootstrap_execution_proof_statement_digest_from_witness_material_v1(
            public_key,
            witness_material,
        )?;
    let material = BfvFullBootstrapExecutionProofInputMaterialV1 {
        version: BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_INPUT_MATERIAL_VERSION_V1,
        field_count: BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_INPUT_MATERIAL_FIELD_COUNT_V1,
        public_key: public_key.clone(),
        witness_material: witness_material.clone(),
        statement_hash,
    };
    validate_bfv_full_bootstrap_execution_proof_input_material_v1(&material)?;
    Ok(material)
}

/// Validate typed proof input material for a dedicated BFV full-bootstrap prover.
///
/// # Errors
/// Returns [`BfvError`] when layout metadata is stale, the embedded witness
/// material is invalid, or the statement hash is not the canonical hash derived
/// from the public key and witness material.
pub fn validate_bfv_full_bootstrap_execution_proof_input_material_v1(
    material: &BfvFullBootstrapExecutionProofInputMaterialV1,
) -> Result<(), BfvError> {
    if material.version != BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_INPUT_MATERIAL_VERSION_V1 {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap execution proof input material version {} does not match canonical version {}",
            material.version, BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_INPUT_MATERIAL_VERSION_V1
        )));
    }
    if material.field_count != BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_INPUT_MATERIAL_FIELD_COUNT_V1 {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap execution proof input material field count {} does not match canonical count {}",
            material.field_count, BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_INPUT_MATERIAL_FIELD_COUNT_V1
        )));
    }
    validate_nonzero_material_digest(
        "BFV full-bootstrap execution proof input statement hash",
        &material.statement_hash,
    )?;
    validate_no_full_bootstrap_placeholder_material_digest(
        "BFV full-bootstrap execution proof input statement hash",
        &material.statement_hash,
    )?;
    let expected_statement_hash =
        bfv_full_bootstrap_execution_proof_statement_digest_from_witness_material_v1(
            &material.public_key,
            &material.witness_material,
        )?;
    if material.statement_hash != expected_statement_hash {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap execution proof input material statement hash mismatch".to_owned(),
        ));
    }
    Ok(())
}

/// Validate execution proof input material against concrete governed artifacts.
///
/// This artifact-aware companion recomputes the embedded witness material from
/// the supplied `FullBootstrapV1` key, artifact bundle, and Galois keys before
/// accepting the proof-input package. Use it when externally held proof input
/// material is available together with the concrete release artifacts.
///
/// # Errors
/// Returns [`BfvError`] when the proof input material is malformed, embeds a
/// witness that does not match the governed artifact trace, or differs from the
/// canonical proof-input package derived from that witness.
pub fn validate_bfv_full_bootstrap_execution_proof_input_material_for_artifacts_v1(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    artifacts: &BfvFullBootstrapCircuitArtifactBundleV1,
    galois_keys: &[BfvGaloisKey],
    material: &BfvFullBootstrapExecutionProofInputMaterialV1,
) -> Result<(), BfvError> {
    validate_bfv_full_bootstrap_execution_proof_input_material_v1(material)?;
    bfv_full_bootstrap_execution_witness_digest_from_material_for_artifacts_v1(
        params,
        bootstrap_key,
        artifacts,
        galois_keys,
        &material.witness_material,
    )?;
    let expected_material = bfv_full_bootstrap_execution_proof_input_material_v1(
        &material.public_key,
        &material.witness_material,
    )?;
    if material != &expected_material {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap execution proof input material does not match governed artifacts"
                .to_owned(),
        ));
    }
    Ok(())
}

/// Hash self-consistent typed proof input material for a BFV full-bootstrap execution proof.
///
/// Prefer [`bfv_full_bootstrap_execution_proof_input_material_digest_for_artifacts_v1`]
/// when the concrete governed artifacts and Galois keys are available.
///
/// # Errors
/// Returns [`BfvError`] when execution proof input validation or canonical
/// Norito encoding fails.
pub fn bfv_full_bootstrap_execution_proof_input_material_digest_v1(
    material: &BfvFullBootstrapExecutionProofInputMaterialV1,
) -> Result<Hash, BfvError> {
    validate_bfv_full_bootstrap_execution_proof_input_material_v1(material)?;
    let bytes = norito::to_bytes(material).map_err(|err| {
        BfvError::InvalidParameters(format!(
            "BFV full-bootstrap execution proof input material encoding failed: {err}"
        ))
    })?;
    Ok(Hash::new_from_chunks(&[
        BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_INPUT_MATERIAL_DIGEST_DOMAIN,
        bytes.as_slice(),
    ]))
}

/// Hash typed proof input material after replaying it against governed artifacts.
///
/// # Errors
/// Returns [`BfvError`] when artifact-aware proof input validation or canonical
/// Norito encoding fails.
pub fn bfv_full_bootstrap_execution_proof_input_material_digest_for_artifacts_v1(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    artifacts: &BfvFullBootstrapCircuitArtifactBundleV1,
    galois_keys: &[BfvGaloisKey],
    material: &BfvFullBootstrapExecutionProofInputMaterialV1,
) -> Result<Hash, BfvError> {
    validate_bfv_full_bootstrap_execution_proof_input_material_for_artifacts_v1(
        params,
        bootstrap_key,
        artifacts,
        galois_keys,
        material,
    )?;
    bfv_full_bootstrap_execution_proof_input_material_digest_v1(material)
}

/// Build row-major native arithmetic trace material for a BFV full-bootstrap proof input.
///
/// # Errors
/// Returns [`BfvError`] when proof input material is invalid, the BFV witness
/// cannot be injectively encoded into the native Goldilocks field, or the
/// canonical trace material fails validation.
pub fn bfv_full_bootstrap_arithmetic_trace_material_v1(
    proof_input_material: &BfvFullBootstrapExecutionProofInputMaterialV1,
) -> Result<BfvFullBootstrapArithmeticTraceMaterialV1, BfvError> {
    validate_bfv_full_bootstrap_execution_proof_input_material_v1(proof_input_material)?;
    let rows = bfv_full_bootstrap_arithmetic_trace_rows_v1(proof_input_material)?;
    let material = BfvFullBootstrapArithmeticTraceMaterialV1 {
        version: BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_MATERIAL_VERSION_V1,
        field_count: BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_MATERIAL_FIELD_COUNT_V1,
        arithmetic_trace_profile_digest:
            canonical_bfv_full_bootstrap_arithmetic_trace_profile_digest_v1(),
        proof_input_material: proof_input_material.clone(),
        row_width: BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_ROW_WIDTH_V1,
        active_row_count: proof_input_material
            .witness_material
            .params
            .polynomial_degree,
        padded_row_count: canonical_bfv_full_bootstrap_arithmetic_trace_padded_row_count_v1(),
        rows,
    };
    validate_bfv_full_bootstrap_arithmetic_trace_material_v1(&material)?;
    Ok(material)
}

/// Validate row-major native arithmetic trace material for a BFV full-bootstrap proof input.
///
/// # Errors
/// Returns [`BfvError`] when layout metadata is stale, proof input material is
/// invalid, rows are not canonical Goldilocks field elements, or the rows do
/// not match the deterministic encoding of the embedded proof input material.
pub fn validate_bfv_full_bootstrap_arithmetic_trace_material_v1(
    material: &BfvFullBootstrapArithmeticTraceMaterialV1,
) -> Result<(), BfvError> {
    if material.version != BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_MATERIAL_VERSION_V1 {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap arithmetic trace material version {} does not match canonical version {}",
            material.version, BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_MATERIAL_VERSION_V1
        )));
    }
    if material.field_count != BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_MATERIAL_FIELD_COUNT_V1 {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap arithmetic trace material field count {} does not match canonical count {}",
            material.field_count, BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_MATERIAL_FIELD_COUNT_V1
        )));
    }
    validate_bfv_full_bootstrap_arithmetic_trace_profile_digest_v1(
        "BFV full-bootstrap arithmetic trace material profile digest",
        &material.arithmetic_trace_profile_digest,
    )?;
    validate_bfv_full_bootstrap_execution_proof_input_material_v1(&material.proof_input_material)?;
    if material.row_width != BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_ROW_WIDTH_V1 {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap arithmetic trace material row width {} does not match canonical width {}",
            material.row_width, BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_ROW_WIDTH_V1
        )));
    }
    let expected_active_rows = material
        .proof_input_material
        .witness_material
        .params
        .polynomial_degree;
    if material.active_row_count != expected_active_rows {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap arithmetic trace material active row count {} does not match polynomial degree {}",
            material.active_row_count, expected_active_rows
        )));
    }
    if material.active_row_count != BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_PRIVATE_ROW_COUNT_V1 {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap arithmetic trace material active row count {} does not match private row count {}",
            material.active_row_count, BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_PRIVATE_ROW_COUNT_V1
        )));
    }
    let expected_padded_rows = canonical_bfv_full_bootstrap_arithmetic_trace_padded_row_count_v1();
    if material.padded_row_count != expected_padded_rows {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap arithmetic trace material padded row count {} does not match canonical count {}",
            material.padded_row_count, expected_padded_rows
        )));
    }
    if material.rows.len() != usize::from(material.padded_row_count) {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap arithmetic trace material row count {} does not match padded row count {}",
            material.rows.len(),
            material.padded_row_count
        )));
    }
    for (row_index, row) in material.rows.iter().enumerate() {
        if row.len() != usize::from(material.row_width) {
            return Err(BfvError::InvalidParameters(format!(
                "BFV full-bootstrap arithmetic trace material row {row_index} width {} does not match canonical width {}",
                row.len(),
                material.row_width
            )));
        }
        for (column_index, &value) in row.iter().enumerate() {
            validate_bfv_full_bootstrap_goldilocks_field_element_v1(
                &format!(
                    "BFV full-bootstrap arithmetic trace row {row_index} column {column_index}"
                ),
                value,
            )?;
        }
    }
    let expected_rows =
        bfv_full_bootstrap_arithmetic_trace_rows_v1(&material.proof_input_material)?;
    if material.rows != expected_rows {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap arithmetic trace material rows do not match deterministic proof input material encoding"
                .to_owned(),
        ));
    }
    Ok(())
}

/// Validate that sampled native AIR openings do not expose private BFV trace rows.
///
/// The canonical row-major full-bootstrap trace stores witness material in
/// active rows and deterministic padding in public rows. Native transparent
/// AIR openings must therefore avoid both `row[index]` and `next_row[index]`
/// touching active rows.
///
/// # Errors
/// Returns [`BfvError`] when no openings are supplied, an index is outside the
/// canonical STARK domain, an index is duplicated, or an opening would reveal an
/// unmasked private row.
pub fn validate_bfv_full_bootstrap_arithmetic_trace_opening_indices_v1(
    opening_indices: &[u32],
) -> Result<(), BfvError> {
    if opening_indices.is_empty() {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap arithmetic trace openings must not be empty".to_owned(),
        ));
    }
    let private_row_count = u32::from(BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_PRIVATE_ROW_COUNT_V1);
    let padded_row_count =
        u32::from(canonical_bfv_full_bootstrap_arithmetic_trace_padded_row_count_v1());
    let mut seen_indices = std::collections::BTreeSet::new();
    for &index in opening_indices {
        if !seen_indices.insert(index) {
            return Err(BfvError::InvalidParameters(format!(
                "BFV full-bootstrap arithmetic trace opening index {index} is duplicated"
            )));
        }
        if index >= padded_row_count {
            return Err(BfvError::InvalidParameters(format!(
                "BFV full-bootstrap arithmetic trace opening index {index} exceeds padded row count {padded_row_count}"
            )));
        }
        let next_index = (index + 1) % padded_row_count;
        if index < private_row_count || next_index < private_row_count {
            return Err(BfvError::InvalidParameters(format!(
                "BFV full-bootstrap arithmetic trace opening index {index} exposes an unmasked private row"
            )));
        }
    }
    Ok(())
}

/// Validate canonical release verifier opening indices for the BFV full-bootstrap trace.
///
/// This is the verifier-facing companion to
/// [`validate_bfv_full_bootstrap_arithmetic_trace_opening_indices_v1`]. It keeps
/// the reusable privacy check while also requiring the exact first-release
/// STARK/FRI query count.
///
/// # Errors
/// Returns [`BfvError`] when the opening count does not match the canonical
/// STARK/FRI query count, or when any index violates the public-row privacy
/// policy.
pub fn validate_bfv_full_bootstrap_arithmetic_trace_canonical_opening_indices_v1(
    opening_indices: &[u32],
) -> Result<(), BfvError> {
    let expected_query_count = usize::from(BFV_FULL_BOOTSTRAP_NATIVE_STARK_FRI_QUERIES_V1);
    if opening_indices.len() != expected_query_count {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap arithmetic trace opening count {} does not match canonical STARK/FRI query count {expected_query_count}",
            opening_indices.len()
        )));
    }
    validate_bfv_full_bootstrap_arithmetic_trace_opening_indices_v1(opening_indices)
}

/// Build one canonical public padding row for the BFV full-bootstrap arithmetic trace.
///
/// Public padding rows carry no ciphertext or witness coefficients. They repeat
/// the public statement header so sampled transparent AIR openings can be
/// checked without exposing private active rows.
///
/// # Errors
/// Returns [`BfvError`] when `row_index` is not a public padding row, the
/// statement hash is the zero sentinel, or public metadata cannot be encoded
/// into the native Goldilocks field.
pub fn bfv_full_bootstrap_arithmetic_trace_public_padding_row_v1(
    row_index: u32,
    statement_hash: Hash,
    slot_index: u32,
    bound_mode: BfvFullBootstrapExecutionProofBoundModeV1,
) -> Result<Vec<u64>, BfvError> {
    validate_nonzero_material_digest(
        "BFV full-bootstrap arithmetic trace public padding statement hash",
        &statement_hash,
    )?;
    validate_no_full_bootstrap_placeholder_material_digest(
        "BFV full-bootstrap arithmetic trace public padding statement hash",
        &statement_hash,
    )?;
    let private_row_count = u32::from(BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_PRIVATE_ROW_COUNT_V1);
    let padded_row_count =
        u32::from(canonical_bfv_full_bootstrap_arithmetic_trace_padded_row_count_v1());
    if row_index < private_row_count {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap arithmetic trace public padding row index {row_index} is private"
        )));
    }
    if row_index >= padded_row_count {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap arithmetic trace public padding row index {row_index} exceeds padded row count {padded_row_count}"
        )));
    }
    let row_index_field = bfv_full_bootstrap_goldilocks_field_from_u128_v1(
        "BFV full-bootstrap arithmetic trace public padding row index",
        u128::from(row_index),
    )?;
    let slot_index_field = bfv_full_bootstrap_goldilocks_field_from_u128_v1(
        "BFV full-bootstrap arithmetic trace public padding slot index",
        u128::from(slot_index),
    )?;
    let mode = bfv_full_bootstrap_bound_mode_goldilocks_field_v1(bound_mode);
    let statement_limbs = bfv_full_bootstrap_hash_goldilocks_limbs_v1(statement_hash);
    let mut row = Vec::with_capacity(usize::from(
        BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_ROW_WIDTH_V1,
    ));
    row.push(BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_ROW_KIND_PADDING_V1);
    row.push(row_index_field);
    row.push(0);
    row.push(slot_index_field);
    row.push(mode);
    row.extend_from_slice(&statement_limbs);
    row.resize(
        usize::from(BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_ROW_WIDTH_V1),
        0,
    );
    Ok(row)
}

/// Validate opened public padding rows from the BFV full-bootstrap arithmetic trace.
///
/// # Errors
/// Returns [`BfvError`] when the sampled index is not public-safe or either
/// opened row differs from the canonical public padding row for its position.
pub fn validate_bfv_full_bootstrap_arithmetic_trace_public_padding_opening_v1(
    opening_index: u32,
    row: &[u64],
    next_row: &[u64],
    statement_hash: Hash,
    slot_index: u32,
    bound_mode: BfvFullBootstrapExecutionProofBoundModeV1,
) -> Result<(), BfvError> {
    validate_bfv_full_bootstrap_arithmetic_trace_opening_indices_v1(&[opening_index])?;
    validate_bfv_full_bootstrap_arithmetic_trace_public_padding_row_v1(
        "row",
        row,
        opening_index,
        statement_hash,
        slot_index,
        bound_mode,
    )?;
    let padded_row_count =
        u32::from(canonical_bfv_full_bootstrap_arithmetic_trace_padded_row_count_v1());
    validate_bfv_full_bootstrap_arithmetic_trace_public_padding_row_v1(
        "next row",
        next_row,
        (opening_index + 1) % padded_row_count,
        statement_hash,
        slot_index,
        bound_mode,
    )?;
    Ok(())
}

fn validate_bfv_full_bootstrap_arithmetic_trace_public_padding_row_v1(
    row_label: &str,
    row: &[u64],
    row_index: u32,
    statement_hash: Hash,
    slot_index: u32,
    bound_mode: BfvFullBootstrapExecutionProofBoundModeV1,
) -> Result<(), BfvError> {
    let expected = bfv_full_bootstrap_arithmetic_trace_public_padding_row_v1(
        row_index,
        statement_hash,
        slot_index,
        bound_mode,
    )?;
    if row != expected.as_slice() {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap arithmetic trace public padding {row_label} does not match canonical row {row_index}"
        )));
    }
    Ok(())
}

/// Hash externally held row-major native arithmetic trace material.
///
/// # Errors
/// Returns [`BfvError`] when trace material validation or canonical Norito
/// encoding fails.
pub fn bfv_full_bootstrap_arithmetic_trace_material_digest_v1(
    material: &BfvFullBootstrapArithmeticTraceMaterialV1,
) -> Result<Hash, BfvError> {
    validate_bfv_full_bootstrap_arithmetic_trace_material_v1(material)?;
    let bytes = norito::to_bytes(material).map_err(|err| {
        BfvError::InvalidParameters(format!(
            "BFV full-bootstrap arithmetic trace material encoding failed: {err}"
        ))
    })?;
    Ok(Hash::new_from_chunks(&[
        BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_MATERIAL_DIGEST_DOMAIN,
        bytes.as_slice(),
    ]))
}

fn bfv_full_bootstrap_goldilocks_add_v1(left: u64, right: u64) -> u64 {
    bfv_full_bootstrap_goldilocks_reduce_u128_v1(u128::from(left) + u128::from(right))
}

fn bfv_full_bootstrap_goldilocks_sub_v1(left: u64, right: u64) -> u64 {
    let modulus = u128::from(BFV_FULL_BOOTSTRAP_NATIVE_STARK_GOLDILOCKS_MODULUS_V1);
    bfv_full_bootstrap_goldilocks_reduce_u128_v1(u128::from(left) + modulus - u128::from(right))
}

fn bfv_full_bootstrap_goldilocks_mul_v1(left: u64, right: u64) -> u64 {
    bfv_full_bootstrap_goldilocks_reduce_u128_v1(u128::from(left) * u128::from(right))
}

fn bfv_full_bootstrap_goldilocks_reduce_u128_v1(value: u128) -> u64 {
    let modulus = u128::from(BFV_FULL_BOOTSTRAP_NATIVE_STARK_GOLDILOCKS_MODULUS_V1);
    u64::try_from(value % modulus)
        .expect("Goldilocks reduction is strictly smaller than the u64 modulus")
}

fn bfv_full_bootstrap_arithmetic_air_composition_challenge_v1(
    statement_hash: Hash,
    trace_material_digest: Hash,
    row_index: usize,
    column_index: usize,
) -> Result<u64, BfvError> {
    let statement_hash_bytes: [u8; Hash::LENGTH] = statement_hash.into();
    let trace_material_digest_bytes: [u8; Hash::LENGTH] = trace_material_digest.into();
    let row_index = u64::try_from(row_index).map_err(|_| {
        BfvError::InvalidParameters(
            "BFV full-bootstrap arithmetic AIR composition row index overflow".to_owned(),
        )
    })?;
    let column_index = u64::try_from(column_index).map_err(|_| {
        BfvError::InvalidParameters(
            "BFV full-bootstrap arithmetic AIR composition column index overflow".to_owned(),
        )
    })?;
    let challenge: [u8; Hash::LENGTH] = Hash::new_from_chunks(&[
        BFV_FULL_BOOTSTRAP_ARITHMETIC_AIR_COMPOSITION_CHALLENGE_DOMAIN,
        statement_hash_bytes.as_slice(),
        trace_material_digest_bytes.as_slice(),
        row_index.to_le_bytes().as_slice(),
        column_index.to_le_bytes().as_slice(),
    ])
    .into();
    let mut low = [0_u8; 8];
    low.copy_from_slice(&challenge[..8]);
    let reduced = bfv_full_bootstrap_goldilocks_reduce_u128_v1(u128::from(u64::from_le_bytes(low)));
    Ok(if reduced == 0 { 1 } else { reduced })
}

fn bfv_full_bootstrap_arithmetic_air_composition_values_for_rows_v1(
    trace_material: &BfvFullBootstrapArithmeticTraceMaterialV1,
    rows: &[Vec<u64>],
) -> Result<Vec<u64>, BfvError> {
    validate_bfv_full_bootstrap_execution_proof_input_material_v1(
        &trace_material.proof_input_material,
    )?;
    if rows.len() != usize::from(trace_material.padded_row_count) {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap arithmetic AIR composition row count {} does not match padded row count {}",
            rows.len(),
            trace_material.padded_row_count
        )));
    }
    let expected_rows =
        bfv_full_bootstrap_arithmetic_trace_rows_v1(&trace_material.proof_input_material)?;
    if rows.len() != expected_rows.len() {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap arithmetic AIR composition expected row count mismatch".to_owned(),
        ));
    }
    let statement_hash = trace_material.proof_input_material.statement_hash;
    let trace_material_digest =
        bfv_full_bootstrap_arithmetic_trace_material_digest_v1(trace_material)?;
    rows.iter()
        .zip(expected_rows.iter())
        .enumerate()
        .map(|(row_index, (row, expected_row))| {
            if row.len() != usize::from(trace_material.row_width) {
                return Err(BfvError::InvalidParameters(format!(
                    "BFV full-bootstrap arithmetic AIR composition row {row_index} width {} does not match trace width {}",
                    row.len(),
                    trace_material.row_width
                )));
            }
            if expected_row.len() != row.len() {
                return Err(BfvError::InvalidParameters(format!(
                    "BFV full-bootstrap arithmetic AIR composition expected row {row_index} width mismatch"
                )));
            }
            let mut composition = 0_u64;
            for (column_index, (&actual, &expected)) in row.iter().zip(expected_row.iter()).enumerate()
            {
                validate_bfv_full_bootstrap_goldilocks_field_element_v1(
                    &format!(
                        "BFV full-bootstrap arithmetic AIR composition row {row_index} column {column_index}"
                    ),
                    actual,
                )?;
                let difference = bfv_full_bootstrap_goldilocks_sub_v1(actual, expected);
                if difference == 0 {
                    continue;
                }
                let challenge = bfv_full_bootstrap_arithmetic_air_composition_challenge_v1(
                    statement_hash,
                    trace_material_digest,
                    row_index,
                    column_index,
                )?;
                composition = bfv_full_bootstrap_goldilocks_add_v1(
                    composition,
                    bfv_full_bootstrap_goldilocks_mul_v1(difference, challenge),
                );
            }
            Ok(composition)
        })
        .collect()
}

/// Evaluate first-release BFV full-bootstrap arithmetic AIR composition values.
///
/// # Errors
/// Returns [`BfvError`] when trace validation fails or the deterministic
/// Goldilocks composition evaluator cannot derive values for the canonical
/// row-major trace.
pub fn bfv_full_bootstrap_arithmetic_air_composition_values_v1(
    trace_material: &BfvFullBootstrapArithmeticTraceMaterialV1,
) -> Result<Vec<u64>, BfvError> {
    validate_bfv_full_bootstrap_arithmetic_trace_material_v1(trace_material)?;
    bfv_full_bootstrap_arithmetic_air_composition_values_for_rows_v1(
        trace_material,
        &trace_material.rows,
    )
}

/// Build first-release AIR evaluation material for a BFV full-bootstrap trace.
///
/// # Errors
/// Returns [`BfvError`] when trace validation fails or the evaluation material
/// cannot be built with the canonical full-domain composition vector.
pub fn bfv_full_bootstrap_arithmetic_air_evaluation_material_v1(
    trace_material: &BfvFullBootstrapArithmeticTraceMaterialV1,
) -> Result<BfvFullBootstrapArithmeticAirEvaluationMaterialV1, BfvError> {
    validate_bfv_full_bootstrap_arithmetic_trace_material_v1(trace_material)?;
    let trace_digest = bfv_full_bootstrap_arithmetic_trace_material_digest_v1(trace_material)?;
    let composition_values =
        bfv_full_bootstrap_arithmetic_air_composition_values_v1(trace_material)?;
    let material = BfvFullBootstrapArithmeticAirEvaluationMaterialV1 {
        version: BFV_FULL_BOOTSTRAP_ARITHMETIC_AIR_EVALUATION_MATERIAL_VERSION_V1,
        field_count: BFV_FULL_BOOTSTRAP_ARITHMETIC_AIR_EVALUATION_MATERIAL_FIELD_COUNT_V1,
        arithmetic_air_constraint_system_digest:
            canonical_bfv_full_bootstrap_arithmetic_air_constraint_system_digest_v1(),
        arithmetic_trace_material_digest: trace_digest,
        trace_row_count: trace_material.padded_row_count,
        trace_row_width: trace_material.row_width,
        composition_value_count: trace_material.padded_row_count,
        composition_values,
    };
    validate_bfv_full_bootstrap_arithmetic_air_evaluation_material_for_trace_v1(
        trace_material,
        &material,
    )?;
    Ok(material)
}

/// Validate first-release BFV full-bootstrap AIR evaluation material.
///
/// # Errors
/// Returns [`BfvError`] when layout metadata, AIR binding, shape, or
/// composition values are not canonical for the first-release AIR.
pub fn validate_bfv_full_bootstrap_arithmetic_air_evaluation_material_v1(
    material: &BfvFullBootstrapArithmeticAirEvaluationMaterialV1,
) -> Result<(), BfvError> {
    if material.version != BFV_FULL_BOOTSTRAP_ARITHMETIC_AIR_EVALUATION_MATERIAL_VERSION_V1 {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap arithmetic AIR evaluation material version {} does not match canonical version {}",
            material.version, BFV_FULL_BOOTSTRAP_ARITHMETIC_AIR_EVALUATION_MATERIAL_VERSION_V1
        )));
    }
    if material.field_count != BFV_FULL_BOOTSTRAP_ARITHMETIC_AIR_EVALUATION_MATERIAL_FIELD_COUNT_V1
    {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap arithmetic AIR evaluation material field count {} does not match canonical count {}",
            material.field_count,
            BFV_FULL_BOOTSTRAP_ARITHMETIC_AIR_EVALUATION_MATERIAL_FIELD_COUNT_V1
        )));
    }
    validate_bfv_full_bootstrap_arithmetic_air_constraint_system_digest_v1(
        "BFV full-bootstrap arithmetic AIR evaluation material constraint-system digest",
        &material.arithmetic_air_constraint_system_digest,
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap arithmetic AIR evaluation material trace material digest",
        &material.arithmetic_trace_material_digest,
    )?;
    validate_no_full_bootstrap_placeholder_material_digest(
        "BFV full-bootstrap arithmetic AIR evaluation material trace material digest",
        &material.arithmetic_trace_material_digest,
    )?;
    let expected_row_count = canonical_bfv_full_bootstrap_arithmetic_trace_padded_row_count_v1();
    if material.trace_row_count != expected_row_count {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap arithmetic AIR evaluation material trace row count {} does not match canonical count {expected_row_count}",
            material.trace_row_count
        )));
    }
    if material.trace_row_width != BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_ROW_WIDTH_V1 {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap arithmetic AIR evaluation material trace row width {} does not match canonical width {}",
            material.trace_row_width, BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_ROW_WIDTH_V1
        )));
    }
    if material.composition_value_count != expected_row_count {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap arithmetic AIR evaluation material composition value count {} does not match canonical count {expected_row_count}",
            material.composition_value_count
        )));
    }
    if material.composition_values.len() != usize::from(material.composition_value_count) {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap arithmetic AIR evaluation material composition value length {} does not match count {}",
            material.composition_values.len(),
            material.composition_value_count
        )));
    }
    for (index, &value) in material.composition_values.iter().enumerate() {
        validate_bfv_full_bootstrap_goldilocks_field_element_v1(
            &format!("BFV full-bootstrap arithmetic AIR evaluation composition value {index}"),
            value,
        )?;
        if value != 0 {
            return Err(BfvError::InvalidParameters(format!(
                "BFV full-bootstrap arithmetic AIR evaluation composition value {index} must be zero"
            )));
        }
    }
    Ok(())
}

/// Validate AIR evaluation material against the row-major trace it evaluates.
///
/// # Errors
/// Returns [`BfvError`] when either material is malformed or the evaluation
/// material does not bind the supplied trace digest and shape.
pub fn validate_bfv_full_bootstrap_arithmetic_air_evaluation_material_for_trace_v1(
    trace_material: &BfvFullBootstrapArithmeticTraceMaterialV1,
    evaluation_material: &BfvFullBootstrapArithmeticAirEvaluationMaterialV1,
) -> Result<(), BfvError> {
    validate_bfv_full_bootstrap_arithmetic_trace_material_v1(trace_material)?;
    validate_bfv_full_bootstrap_arithmetic_air_evaluation_material_v1(evaluation_material)?;
    let expected_trace_digest =
        bfv_full_bootstrap_arithmetic_trace_material_digest_v1(trace_material)?;
    if evaluation_material.arithmetic_trace_material_digest != expected_trace_digest {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap arithmetic AIR evaluation material trace material digest mismatch"
                .to_owned(),
        ));
    }
    if evaluation_material.trace_row_count != trace_material.padded_row_count {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap arithmetic AIR evaluation material trace row count does not match trace material"
                .to_owned(),
        ));
    }
    if evaluation_material.trace_row_width != trace_material.row_width {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap arithmetic AIR evaluation material trace row width does not match trace material"
                .to_owned(),
        ));
    }
    let expected_composition_values =
        bfv_full_bootstrap_arithmetic_air_composition_values_v1(trace_material)?;
    if evaluation_material.composition_values != expected_composition_values {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap arithmetic AIR evaluation material composition values do not match trace material"
                .to_owned(),
        ));
    }
    Ok(())
}

/// Hash shape-valid typed AIR evaluation material for a BFV full-bootstrap trace.
///
/// Prefer [`bfv_full_bootstrap_arithmetic_air_evaluation_material_digest_for_trace_v1`]
/// when the corresponding arithmetic trace material is available.
///
/// # Errors
/// Returns [`BfvError`] when evaluation material validation or canonical Norito
/// encoding fails.
pub fn bfv_full_bootstrap_arithmetic_air_evaluation_material_digest_v1(
    material: &BfvFullBootstrapArithmeticAirEvaluationMaterialV1,
) -> Result<Hash, BfvError> {
    validate_bfv_full_bootstrap_arithmetic_air_evaluation_material_v1(material)?;
    let bytes = norito::to_bytes(material).map_err(|err| {
        BfvError::InvalidParameters(format!(
            "BFV full-bootstrap arithmetic AIR evaluation material encoding failed: {err}"
        ))
    })?;
    Ok(Hash::new_from_chunks(&[
        BFV_FULL_BOOTSTRAP_ARITHMETIC_AIR_EVALUATION_MATERIAL_DIGEST_DOMAIN,
        bytes.as_slice(),
    ]))
}

/// Hash typed AIR evaluation material after binding it to a BFV full-bootstrap trace.
///
/// # Errors
/// Returns [`BfvError`] when evaluation material validation, trace-bound AIR
/// composition validation, or canonical Norito encoding fails.
pub fn bfv_full_bootstrap_arithmetic_air_evaluation_material_digest_for_trace_v1(
    trace_material: &BfvFullBootstrapArithmeticTraceMaterialV1,
    material: &BfvFullBootstrapArithmeticAirEvaluationMaterialV1,
) -> Result<Hash, BfvError> {
    validate_bfv_full_bootstrap_arithmetic_air_evaluation_material_for_trace_v1(
        trace_material,
        material,
    )?;
    bfv_full_bootstrap_arithmetic_air_evaluation_material_digest_v1(material)
}

/// Build typed release-prover input material for a BFV full-bootstrap proof.
///
/// # Errors
/// Returns [`BfvError`] when proof input material, the derived arithmetic trace,
/// or the supplied generated prover/verifier proof-key pair is malformed or not
/// governed by the full-bootstrap material bound into the witness.
pub fn bfv_full_bootstrap_execution_prover_input_material_v1(
    proof_input_material: &BfvFullBootstrapExecutionProofInputMaterialV1,
    prover_key: &BfvFullBootstrapProofKeyV1,
    verifier_key: &BfvFullBootstrapProofKeyV1,
) -> Result<BfvFullBootstrapExecutionProverInputMaterialV1, BfvError> {
    validate_bfv_full_bootstrap_execution_proof_input_material_v1(proof_input_material)?;
    let governed_material =
        full_bootstrap_material_from_key(&proof_input_material.witness_material.bootstrap_key)?;
    let arithmetic_trace_material =
        bfv_full_bootstrap_arithmetic_trace_material_v1(proof_input_material)?;
    let arithmetic_trace_material_digest =
        bfv_full_bootstrap_arithmetic_trace_material_digest_v1(&arithmetic_trace_material)?;
    let arithmetic_air_evaluation_material =
        bfv_full_bootstrap_arithmetic_air_evaluation_material_v1(&arithmetic_trace_material)?;
    let arithmetic_air_evaluation_material_digest =
        bfv_full_bootstrap_arithmetic_air_evaluation_material_digest_for_trace_v1(
            &arithmetic_trace_material,
            &arithmetic_air_evaluation_material,
        )?;
    let material = BfvFullBootstrapExecutionProverInputMaterialV1 {
        version: BFV_FULL_BOOTSTRAP_EXECUTION_PROVER_INPUT_MATERIAL_VERSION_V1,
        field_count: BFV_FULL_BOOTSTRAP_EXECUTION_PROVER_INPUT_MATERIAL_FIELD_COUNT_V1,
        proof_input_material: proof_input_material.clone(),
        arithmetic_trace_material,
        arithmetic_trace_material_digest,
        arithmetic_air_constraint_system_digest:
            canonical_bfv_full_bootstrap_arithmetic_air_constraint_system_digest_v1(),
        arithmetic_air_constraint_system_artifact_digest: governed_material
            .arithmetic_air_constraint_system_artifact_digest,
        arithmetic_air_evaluation_material,
        arithmetic_air_evaluation_material_digest,
        prover_key: prover_key.clone(),
        verifier_key: verifier_key.clone(),
    };
    validate_bfv_full_bootstrap_execution_prover_input_material_v1(&material)?;
    Ok(material)
}

/// Validate typed release-prover input material for a BFV full-bootstrap proof.
///
/// # Errors
/// Returns [`BfvError`] when layout metadata is stale, the arithmetic trace is
/// not the canonical trace for the embedded proof input, the trace digest, AIR
/// binding, or AIR evaluation material is stale, or the prover/verifier proof
/// keys are not the governed generated pair for the full-bootstrap material.
pub fn validate_bfv_full_bootstrap_execution_prover_input_material_v1(
    material: &BfvFullBootstrapExecutionProverInputMaterialV1,
) -> Result<(), BfvError> {
    if material.version != BFV_FULL_BOOTSTRAP_EXECUTION_PROVER_INPUT_MATERIAL_VERSION_V1 {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap execution prover input material version {} does not match canonical version {}",
            material.version, BFV_FULL_BOOTSTRAP_EXECUTION_PROVER_INPUT_MATERIAL_VERSION_V1
        )));
    }
    if material.field_count != BFV_FULL_BOOTSTRAP_EXECUTION_PROVER_INPUT_MATERIAL_FIELD_COUNT_V1 {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap execution prover input material field count {} does not match canonical count {}",
            material.field_count, BFV_FULL_BOOTSTRAP_EXECUTION_PROVER_INPUT_MATERIAL_FIELD_COUNT_V1
        )));
    }
    validate_bfv_full_bootstrap_execution_proof_input_material_v1(&material.proof_input_material)?;
    validate_bfv_full_bootstrap_arithmetic_trace_material_v1(&material.arithmetic_trace_material)?;
    if material.arithmetic_trace_material.proof_input_material != material.proof_input_material {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap execution prover input material proof input does not match arithmetic trace material"
                .to_owned(),
        ));
    }
    validate_nonzero_material_digest(
        "BFV full-bootstrap execution prover input arithmetic trace material digest",
        &material.arithmetic_trace_material_digest,
    )?;
    validate_no_full_bootstrap_placeholder_material_digest(
        "BFV full-bootstrap execution prover input arithmetic trace material digest",
        &material.arithmetic_trace_material_digest,
    )?;
    let expected_trace_digest = bfv_full_bootstrap_arithmetic_trace_material_digest_v1(
        &material.arithmetic_trace_material,
    )?;
    if material.arithmetic_trace_material_digest != expected_trace_digest {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap execution prover input material arithmetic trace material digest mismatch"
                .to_owned(),
        ));
    }
    let governed_material = full_bootstrap_material_from_key(
        &material.proof_input_material.witness_material.bootstrap_key,
    )?;
    validate_bfv_full_bootstrap_arithmetic_air_constraint_system_digest_v1(
        "BFV full-bootstrap execution prover input material arithmetic AIR constraint-system digest",
        &material.arithmetic_air_constraint_system_digest,
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap execution prover input material arithmetic AIR artifact digest",
        &material.arithmetic_air_constraint_system_artifact_digest,
    )?;
    validate_no_full_bootstrap_placeholder_material_digest(
        "BFV full-bootstrap execution prover input material arithmetic AIR artifact digest",
        &material.arithmetic_air_constraint_system_artifact_digest,
    )?;
    if material.arithmetic_air_constraint_system_artifact_digest
        != governed_material.arithmetic_air_constraint_system_artifact_digest
    {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap execution prover input material arithmetic AIR artifact digest mismatch"
                .to_owned(),
        ));
    }
    validate_nonzero_material_digest(
        "BFV full-bootstrap execution prover input material arithmetic AIR evaluation material digest",
        &material.arithmetic_air_evaluation_material_digest,
    )?;
    validate_no_full_bootstrap_placeholder_material_digest(
        "BFV full-bootstrap execution prover input material arithmetic AIR evaluation material digest",
        &material.arithmetic_air_evaluation_material_digest,
    )?;
    let expected_air_evaluation_digest =
        bfv_full_bootstrap_arithmetic_air_evaluation_material_digest_for_trace_v1(
            &material.arithmetic_trace_material,
            &material.arithmetic_air_evaluation_material,
        )?;
    if material.arithmetic_air_evaluation_material_digest != expected_air_evaluation_digest {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap execution prover input material arithmetic AIR evaluation material digest mismatch"
                .to_owned(),
        ));
    }
    validate_bfv_full_bootstrap_proof_key_v1(
        governed_material,
        BfvFullBootstrapCircuitArtifactRoleV1::ProverKey,
        &material.prover_key,
    )?;
    validate_bfv_full_bootstrap_proof_key_v1(
        governed_material,
        BfvFullBootstrapCircuitArtifactRoleV1::VerifierKey,
        &material.verifier_key,
    )?;
    validate_bfv_full_bootstrap_generated_proof_key_pair_v1(
        &material.prover_key,
        &material.verifier_key,
    )?;
    Ok(())
}

/// Validate release-prover input material against concrete governed artifacts.
///
/// This artifact-aware companion recomputes the execution witness trace from
/// the supplied `FullBootstrapV1` key, artifact bundle, and Galois keys, then
/// decodes the governed prover/verifier key artifacts and checks that the
/// supplied prover input material is exactly the canonical package derived from
/// those bytes.
///
/// # Errors
/// Returns [`BfvError`] when the prover input material is malformed, its
/// embedded witness does not match the governed artifact trace, its proof keys
/// do not match the governed proof-key artifacts, or the canonical prover input
/// package differs from the supplied material.
pub fn validate_bfv_full_bootstrap_execution_prover_input_material_for_artifacts_v1(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    artifacts: &BfvFullBootstrapCircuitArtifactBundleV1,
    galois_keys: &[BfvGaloisKey],
    material: &BfvFullBootstrapExecutionProverInputMaterialV1,
) -> Result<(), BfvError> {
    validate_bfv_full_bootstrap_execution_prover_input_material_v1(material)?;
    bfv_full_bootstrap_execution_proof_input_material_digest_for_artifacts_v1(
        params,
        bootstrap_key,
        artifacts,
        galois_keys,
        &material.proof_input_material,
    )?;
    let governed_material = full_bootstrap_material_from_key(bootstrap_key)?;
    let expected_prover_key = decode_bfv_full_bootstrap_proof_key_artifact_v1(
        params,
        governed_material,
        BfvFullBootstrapCircuitArtifactRoleV1::ProverKey,
        &artifacts.prover_key,
    )?;
    if material.prover_key != expected_prover_key {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap execution prover input material prover key does not match governed artifact"
                .to_owned(),
        ));
    }
    let expected_verifier_key = decode_bfv_full_bootstrap_proof_key_artifact_v1(
        params,
        governed_material,
        BfvFullBootstrapCircuitArtifactRoleV1::VerifierKey,
        &artifacts.verifier_key,
    )?;
    if material.verifier_key != expected_verifier_key {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap execution prover input material verifier key does not match governed artifact"
                .to_owned(),
        ));
    }
    let expected_material = bfv_full_bootstrap_execution_prover_input_material_v1(
        &material.proof_input_material,
        &expected_prover_key,
        &expected_verifier_key,
    )?;
    if material != &expected_material {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap execution prover input material does not match governed artifacts"
                .to_owned(),
        ));
    }
    Ok(())
}

/// Hash self-consistent typed release-prover input material for a BFV full-bootstrap proof.
///
/// Prefer [`bfv_full_bootstrap_execution_prover_input_material_digest_for_artifacts_v1`]
/// when the concrete governed artifacts and Galois keys are available.
///
/// # Errors
/// Returns [`BfvError`] when prover input validation or canonical Norito
/// encoding fails.
pub fn bfv_full_bootstrap_execution_prover_input_material_digest_v1(
    material: &BfvFullBootstrapExecutionProverInputMaterialV1,
) -> Result<Hash, BfvError> {
    validate_bfv_full_bootstrap_execution_prover_input_material_v1(material)?;
    let bytes = norito::to_bytes(material).map_err(|err| {
        BfvError::InvalidParameters(format!(
            "BFV full-bootstrap execution prover input material encoding failed: {err}"
        ))
    })?;
    Ok(Hash::new_from_chunks(&[
        BFV_FULL_BOOTSTRAP_EXECUTION_PROVER_INPUT_MATERIAL_DIGEST_DOMAIN,
        bytes.as_slice(),
    ]))
}

/// Hash typed release-prover input material after replaying it against governed artifacts.
///
/// # Errors
/// Returns [`BfvError`] when artifact-aware prover input validation or
/// canonical Norito encoding fails.
pub fn bfv_full_bootstrap_execution_prover_input_material_digest_for_artifacts_v1(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    artifacts: &BfvFullBootstrapCircuitArtifactBundleV1,
    galois_keys: &[BfvGaloisKey],
    material: &BfvFullBootstrapExecutionProverInputMaterialV1,
) -> Result<Hash, BfvError> {
    validate_bfv_full_bootstrap_execution_prover_input_material_for_artifacts_v1(
        params,
        bootstrap_key,
        artifacts,
        galois_keys,
        material,
    )?;
    bfv_full_bootstrap_execution_prover_input_material_digest_v1(material)
}

#[allow(clippy::too_many_lines)]
fn bfv_full_bootstrap_arithmetic_trace_rows_v1(
    proof_input_material: &BfvFullBootstrapExecutionProofInputMaterialV1,
) -> Result<Vec<Vec<u64>>, BfvError> {
    validate_bfv_full_bootstrap_execution_proof_input_material_v1(proof_input_material)?;
    let witness = &proof_input_material.witness_material;
    let params = &witness.params;
    let active_rows = params.degree();
    let padded_rows =
        usize::from(canonical_bfv_full_bootstrap_arithmetic_trace_padded_row_count_v1());
    if active_rows > padded_rows {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap arithmetic trace active rows {active_rows} exceed padded STARK rows {padded_rows}"
        )));
    }
    let statement_limbs =
        bfv_full_bootstrap_hash_goldilocks_limbs_v1(proof_input_material.statement_hash);
    let mode = bfv_full_bootstrap_bound_mode_goldilocks_field_v1(witness.bound_mode);
    let slot_index = bfv_full_bootstrap_goldilocks_field_from_u128_v1(
        "BFV full-bootstrap arithmetic trace slot index",
        u128::from(witness.slot_index),
    )?;
    let input_bound = bfv_full_bootstrap_goldilocks_field_from_u128_v1(
        "BFV full-bootstrap arithmetic trace input bound",
        witness.input_bound,
    )?;
    let output_bound = bfv_full_bootstrap_goldilocks_field_from_u128_v1(
        "BFV full-bootstrap arithmetic trace output bound",
        witness.output_bound,
    )?;
    let bounds = [
        bfv_full_bootstrap_goldilocks_field_from_u128_v1(
            "BFV full-bootstrap arithmetic trace coefficient-to-slot bound",
            witness.trace_bounds.coefficient_to_slot,
        )?,
        bfv_full_bootstrap_goldilocks_field_from_u128_v1(
            "BFV full-bootstrap arithmetic trace blind-rotation bound",
            witness.trace_bounds.blind_rotation,
        )?,
        bfv_full_bootstrap_goldilocks_field_from_u128_v1(
            "BFV full-bootstrap arithmetic trace raw extracted sample bound",
            witness.trace_bounds.raw_extracted_sample,
        )?,
        bfv_full_bootstrap_goldilocks_field_from_u128_v1(
            "BFV full-bootstrap arithmetic trace coefficient-zero repack bound",
            witness.trace_bounds.coefficient_zero_repack,
        )?,
        bfv_full_bootstrap_goldilocks_field_from_u128_v1(
            "BFV full-bootstrap arithmetic trace sample-switch bound",
            witness.trace_bounds.sample_switch,
        )?,
        bfv_full_bootstrap_goldilocks_field_from_u128_v1(
            "BFV full-bootstrap arithmetic trace slot-to-coefficient bound",
            witness.trace_bounds.slot_to_coefficient,
        )?,
    ];
    let mut rows = Vec::with_capacity(padded_rows);
    for row_index in 0..padded_rows {
        let row_index_field = bfv_full_bootstrap_goldilocks_field_from_u128_v1(
            "BFV full-bootstrap arithmetic trace row index",
            u128::try_from(row_index).map_err(|_| {
                BfvError::InvalidParameters(
                    "BFV full-bootstrap arithmetic trace row index overflow".to_owned(),
                )
            })?,
        )?;
        let mut row = Vec::with_capacity(usize::from(
            BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_ROW_WIDTH_V1,
        ));
        if row_index < active_rows {
            let coefficient_index = row_index;
            row.push(BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_ROW_KIND_ACTIVE_V1);
            row.push(row_index_field);
            row.push(bfv_full_bootstrap_goldilocks_field_from_u128_v1(
                "BFV full-bootstrap arithmetic trace coefficient index",
                u128::try_from(coefficient_index).map_err(|_| {
                    BfvError::InvalidParameters(
                        "BFV full-bootstrap arithmetic trace coefficient index overflow".to_owned(),
                    )
                })?,
            )?);
            row.push(slot_index);
            row.push(mode);
            row.extend_from_slice(&statement_limbs);
            push_bfv_full_bootstrap_ciphertext_trace_coefficients_v1(
                &mut row,
                "input ciphertext",
                &witness.input_ciphertext,
                coefficient_index,
            )?;
            push_bfv_full_bootstrap_ciphertext_trace_coefficients_v1(
                &mut row,
                "coefficient-to-slot output",
                &witness.trace.coefficient_to_slot_output,
                coefficient_index,
            )?;
            push_bfv_full_bootstrap_ciphertext_trace_coefficients_v1(
                &mut row,
                "blind-rotation output",
                &witness.trace.blind_rotation_output,
                coefficient_index,
            )?;
            row.push(bfv_full_bootstrap_goldilocks_field_from_u128_v1(
                "BFV full-bootstrap arithmetic trace raw sample source index",
                u128::from(witness.trace.raw_extracted_sample.source_coefficient_index),
            )?);
            row.push(bfv_full_bootstrap_goldilocks_field_from_u128_v1(
                "BFV full-bootstrap arithmetic trace raw sample constant",
                u128::from(witness.trace.raw_extracted_sample.constant_term),
            )?);
            row.push(bfv_full_bootstrap_goldilocks_field_from_u128_v1(
                "BFV full-bootstrap arithmetic trace raw sample secret coefficient",
                u128::from(
                    witness.trace.raw_extracted_sample.secret_coefficients[coefficient_index],
                ),
            )?);
            push_bfv_full_bootstrap_ciphertext_trace_coefficients_v1(
                &mut row,
                "coefficient-zero repack output",
                &witness.trace.coefficient_zero_repack_output,
                coefficient_index,
            )?;
            push_bfv_full_bootstrap_ciphertext_trace_coefficients_v1(
                &mut row,
                "diagnostic slot-to-coefficient output",
                &witness.trace.diagnostic_slot_to_coefficient_output,
                coefficient_index,
            )?;
            push_bfv_full_bootstrap_ciphertext_trace_coefficients_v1(
                &mut row,
                "sample-switch output",
                &witness.trace.sample_switch_output,
                coefficient_index,
            )?;
            push_bfv_full_bootstrap_ciphertext_trace_coefficients_v1(
                &mut row,
                "slot-to-coefficient output",
                &witness.trace.slot_to_coefficient_output,
                coefficient_index,
            )?;
            row.push(input_bound);
            row.push(output_bound);
            row.extend_from_slice(&bounds);
        } else {
            row.push(BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_ROW_KIND_PADDING_V1);
            row.push(row_index_field);
            row.push(0);
            row.push(slot_index);
            row.push(mode);
            row.extend_from_slice(&statement_limbs);
            row.resize(
                usize::from(BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_ROW_WIDTH_V1),
                0,
            );
        }
        if row.len() != usize::from(BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_ROW_WIDTH_V1) {
            return Err(BfvError::InvalidParameters(format!(
                "BFV full-bootstrap arithmetic trace row {row_index} has width {} instead of {}",
                row.len(),
                BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_ROW_WIDTH_V1
            )));
        }
        rows.push(row);
    }
    Ok(rows)
}

fn push_bfv_full_bootstrap_ciphertext_trace_coefficients_v1(
    row: &mut Vec<u64>,
    label: &str,
    ciphertext: &BfvCiphertext,
    coefficient_index: usize,
) -> Result<(), BfvError> {
    row.push(bfv_full_bootstrap_goldilocks_field_from_u128_v1(
        &format!("BFV full-bootstrap arithmetic trace {label} c0 coefficient"),
        u128::from(ciphertext.c0[coefficient_index]),
    )?);
    row.push(bfv_full_bootstrap_goldilocks_field_from_u128_v1(
        &format!("BFV full-bootstrap arithmetic trace {label} c1 coefficient"),
        u128::from(ciphertext.c1[coefficient_index]),
    )?);
    Ok(())
}

fn bfv_full_bootstrap_bound_mode_goldilocks_field_v1(
    mode: BfvFullBootstrapExecutionProofBoundModeV1,
) -> u64 {
    match mode {
        BfvFullBootstrapExecutionProofBoundModeV1::ExactResidualMultiple => 0,
        BfvFullBootstrapExecutionProofBoundModeV1::BoundedNoise => 1,
    }
}

fn bfv_full_bootstrap_hash_goldilocks_limbs_v1(hash: Hash) -> [u64; 4] {
    let bytes: [u8; Hash::LENGTH] = hash.into();
    let mut limbs = [0_u64; 4];
    for (index, chunk) in bytes.chunks_exact(8).enumerate() {
        let mut word = [0_u8; 8];
        word.copy_from_slice(chunk);
        let reduced = u128::from(u64::from_le_bytes(word))
            % u128::from(BFV_FULL_BOOTSTRAP_NATIVE_STARK_GOLDILOCKS_MODULUS_V1);
        limbs[index] = u64::try_from(reduced).expect("Goldilocks field limb fits u64");
    }
    limbs
}

/// Return the statement-bound native BFV full-bootstrap STARK/AIR domain tag.
#[must_use]
pub fn bfv_full_bootstrap_native_stark_air_domain_tag_v1(statement_hash: Hash) -> String {
    let statement_hash_bytes: [u8; Hash::LENGTH] = statement_hash.into();
    let domain_tag_digest: [u8; Hash::LENGTH] = Hash::new_from_chunks(&[
        BFV_FULL_BOOTSTRAP_NATIVE_STARK_AIR_DOMAIN_TAG_DOMAIN,
        &statement_hash_bytes,
    ])
    .into();
    hex::encode(domain_tag_digest)
}

fn bfv_full_bootstrap_goldilocks_field_from_u128_v1(
    label: &str,
    value: u128,
) -> Result<u64, BfvError> {
    if value >= u128::from(BFV_FULL_BOOTSTRAP_NATIVE_STARK_GOLDILOCKS_MODULUS_V1) {
        return Err(BfvError::InvalidParameters(format!(
            "{label} value {value} cannot be injectively encoded in the native Goldilocks field"
        )));
    }
    u64::try_from(value).map_err(|_| {
        BfvError::InvalidParameters(format!(
            "{label} value {value} exceeds native u64 field element range"
        ))
    })
}

fn validate_bfv_full_bootstrap_goldilocks_field_element_v1(
    label: &str,
    value: u64,
) -> Result<(), BfvError> {
    if value >= BFV_FULL_BOOTSTRAP_NATIVE_STARK_GOLDILOCKS_MODULUS_V1 {
        return Err(BfvError::InvalidParameters(format!(
            "{label} is not a canonical native Goldilocks field element"
        )));
    }
    Ok(())
}

/// Build a full-bootstrap execution proof claim with its deterministic witness digest.
///
/// # Errors
/// Returns [`BfvError`] when the governed execution witness cannot be derived
/// or when the supplied output ciphertext/bound do not match that witness.
#[allow(clippy::too_many_arguments)]
pub fn bfv_full_bootstrap_execution_proof_claim_with_witness_digest_v1(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    artifacts: &BfvFullBootstrapCircuitArtifactBundleV1,
    galois_keys: &[BfvGaloisKey],
    slot_index: u32,
    input_ciphertext: BfvCiphertext,
    output_ciphertext: BfvCiphertext,
    bound_mode: BfvFullBootstrapExecutionProofBoundModeV1,
    input_bound: u128,
    output_bound: u128,
) -> Result<BfvFullBootstrapExecutionProofClaimV1, BfvError> {
    let claim = BfvFullBootstrapExecutionProofClaimV1 {
        slot_index,
        input_ciphertext,
        output_ciphertext,
        bound_mode,
        input_bound,
        output_bound,
        execution_witness_digest: Hash::new(
            b"transient BFV full-bootstrap execution witness digest before finalization v1",
        ),
    };
    let execution_witness_digest = bfv_full_bootstrap_execution_witness_digest_v1(
        params,
        bootstrap_key,
        artifacts,
        galois_keys,
        &claim,
    )?;
    Ok(BfvFullBootstrapExecutionProofClaimV1 {
        execution_witness_digest,
        ..claim
    })
}

/// Return the statement digest after verifying the claim's execution witness digest.
///
/// # Errors
/// Returns [`BfvError`] when the witness digest does not match the governed
/// arithmetic trace or when the canonical statement digest cannot be derived.
pub fn bfv_full_bootstrap_execution_proof_statement_digest_with_witness_v1(
    params: &BfvParameters,
    public_key: &BfvPublicKey,
    bootstrap_key: &BfvBootstrapKey,
    artifacts: &BfvFullBootstrapCircuitArtifactBundleV1,
    galois_keys: &[BfvGaloisKey],
    claim: &BfvFullBootstrapExecutionProofClaimV1,
) -> Result<Hash, BfvError> {
    let expected_witness_digest = bfv_full_bootstrap_execution_witness_digest_v1(
        params,
        bootstrap_key,
        artifacts,
        galois_keys,
        claim,
    )?;
    if claim.execution_witness_digest != expected_witness_digest {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap execution proof witness digest mismatch".to_owned(),
        ));
    }
    bfv_full_bootstrap_execution_proof_statement_digest_v1(
        params,
        public_key,
        bootstrap_key,
        artifacts,
        claim,
    )
}

/// Return the public statement digest for one claimed full-bootstrap execution.
///
/// This statement is the proof-facing binding for a concrete input/output
/// bootstrap claim. It validates the public key, full-bootstrap
/// key/material/artifact preflight, input and output ciphertext shapes, and the
/// exact or bounded-noise metadata before hashing the canonical statement. Use
/// [`bfv_full_bootstrap_execution_proof_statement_digest_with_witness_v1`] when
/// the caller has governed Galois keys and needs to recompute the arithmetic
/// trace before accepting the claim.
///
/// # Errors
/// Returns [`BfvError`] when public metadata is malformed, full-bootstrap
/// material/artifacts do not validate, exact/bounded metadata exceeds capacity,
/// or canonical statement encoding fails.
pub fn bfv_full_bootstrap_execution_proof_statement_digest_v1(
    params: &BfvParameters,
    public_key: &BfvPublicKey,
    bootstrap_key: &BfvBootstrapKey,
    artifacts: &BfvFullBootstrapCircuitArtifactBundleV1,
    claim: &BfvFullBootstrapExecutionProofClaimV1,
) -> Result<Hash, BfvError> {
    validate_public_key(params, public_key)?;
    validate_bootstrap_key_public_key_digest(params, public_key, bootstrap_key)?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap execution witness digest",
        &claim.execution_witness_digest,
    )?;
    validate_no_full_bootstrap_placeholder_material_digest(
        "BFV full-bootstrap execution witness digest",
        &claim.execution_witness_digest,
    )?;
    if usize::try_from(claim.slot_index).map_or(true, |slot_index| slot_index >= params.degree()) {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap execution proof slot index exceeds parameter slot capacity"
                .to_owned(),
        ));
    }
    validate_bfv_full_bootstrap_execution_artifacts_preflight_v1(
        params,
        bootstrap_key,
        &claim.input_ciphertext,
        artifacts,
    )?;
    validate_ciphertext_not_all_zero(
        "BFV full-bootstrap execution proof input ciphertext",
        &claim.input_ciphertext,
    )?;
    validate_ciphertext(params, &claim.output_ciphertext)?;
    validate_ciphertext_not_all_zero(
        "BFV full-bootstrap execution proof output ciphertext",
        &claim.output_ciphertext,
    )?;
    match claim.bound_mode {
        BfvFullBootstrapExecutionProofBoundModeV1::ExactResidualMultiple => {
            validate_exact_residual_bound_within_centered_capacity(
                params,
                claim.input_bound,
                "BFV full-bootstrap execution proof input residual bound",
            )?;
            validate_exact_residual_bound_within_centered_capacity(
                params,
                claim.output_bound,
                "BFV full-bootstrap execution proof output residual bound",
            )?;
        }
        BfvFullBootstrapExecutionProofBoundModeV1::BoundedNoise => {
            validate_bfv_bounded_noise_encryption_capacity(params)?;
            validate_bounded_noise_bound_within_decoding_capacity(
                params,
                claim.input_bound,
                "BFV full-bootstrap execution proof input bounded-noise bound",
            )?;
            validate_bounded_noise_bound_within_decoding_capacity(
                params,
                claim.output_bound,
                "BFV full-bootstrap execution proof output bounded-noise bound",
            )?;
        }
    }
    let material = bootstrap_key
        .full_bootstrap_material
        .as_ref()
        .ok_or_else(|| {
            BfvError::InvalidParameters(
                "full BFV bootstrap key mode requires bootstrapping circuit material".to_owned(),
            )
        })?;
    let full_bootstrap_material_digest =
        bfv_full_bootstrap_circuit_material_digest(params, material)?;
    let artifact_bundle_digest =
        bfv_full_bootstrap_circuit_artifact_bundle_digest(params, material, artifacts)?;
    let statement = BfvFullBootstrapExecutionProofStatementMaterial {
        version: BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_STATEMENT_MATERIAL_VERSION_V1,
        field_count: BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_STATEMENT_MATERIAL_FIELD_COUNT_V1,
        params: *params,
        public_key: public_key.clone(),
        bootstrap_key: bootstrap_key.clone(),
        full_bootstrap_material_digest,
        artifact_bundle_digest,
        claim: claim.clone(),
    };
    let bytes = norito::to_bytes(&statement).map_err(|err| {
        BfvError::InvalidParameters(format!(
            "full-bootstrap execution proof statement encoding failed: {err}"
        ))
    })?;
    Ok(Hash::new_from_chunks(&[
        BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_STATEMENT_DOMAIN,
        bytes.as_slice(),
    ]))
}

/// Apply a typed full-bootstrap packed-slot linear transform through registered exact RNS paths.
///
/// This evaluates the diagonal transform schema used by coefficient-to-slot
/// and slot-to-coefficient artifacts. Each diagonal uses an existing packed
/// Galois rotation, a plaintext mask product, and registered exact RNS
/// accumulation, so the result is deterministic across hardware.
///
/// # Errors
/// Returns [`BfvError`] when the transform, ciphertext, required Galois keys, or
/// registered RNS profile are invalid.
pub fn apply_bfv_full_bootstrap_linear_transform_registered_rns_exact_v1(
    params: &BfvParameters,
    galois_keys: &[BfvGaloisKey],
    ciphertext: &BfvCiphertext,
    transform: &BfvFullBootstrapLinearTransformV1,
) -> Result<BfvCiphertext, BfvError> {
    let _rns_chain = registered_bfv_rns_modulus_chain(params)?;
    validate_bfv_full_bootstrap_linear_transform_v1(params, transform)?;
    validate_ciphertext(params, ciphertext)?;
    let mut output: Option<BfvCiphertext> = None;
    for diagonal in &transform.diagonals {
        let rotated = if diagonal.rotation_steps == 0 {
            ciphertext.clone()
        } else {
            rotate_packed_ciphertext_slots_left_with_galois_keys_registered_rns_exact(
                params,
                galois_keys,
                ciphertext,
                diagonal.rotation_steps,
            )?
        };
        let masked = multiply_plaintext_polynomial_registered_rns_exact(
            params,
            &rotated,
            &diagonal.plaintext,
        )?;
        output = Some(match output {
            Some(accumulator) => {
                add_ciphertexts_registered_rns_exact(params, &accumulator, &masked)?
            }
            None => masked,
        });
    }
    output.ok_or_else(|| {
        BfvError::InvalidParameters(
            "BFV full-bootstrap linear transform produced an empty accumulator".to_owned(),
        )
    })
}

