    #[test]
    fn homomorphic_plaintext_polynomial_multiplication_matches_packed_mask() {
        let params = ram_lfe_bfv_parameters_v1();
        let chain = registered_bfv_rns_modulus_chain(&params).expect("registered RNS chain");
        let (secret_key, public_key, _) =
            keygen_from_seed(&params, b"bfv-packed-mask-keygen").expect("keygen");
        let slots = (0..params.degree())
            .map(|index| u64::try_from(index + 1).expect("slot index fits u64"))
            .collect::<Vec<_>>();
        let mask_slots = (0..params.degree())
            .map(|index| u64::from(index % 3 == 0))
            .collect::<Vec<_>>();
        let packed_plaintext =
            encode_packed_plaintext_slots(&params, &slots).expect("encode packed slots");
        let mask_plaintext =
            encode_packed_plaintext_slots(&params, &mask_slots).expect("encode packed mask");
        let ciphertext = encrypt_from_seed(
            &params,
            &public_key,
            &packed_plaintext,
            b"bfv-packed-mask-input",
        )
        .expect("encrypt packed input");

        let masked = multiply_plaintext_polynomial(&params, &ciphertext, &mask_plaintext)
            .expect("multiply by packed plaintext mask");
        let rns_masked =
            multiply_plaintext_polynomial_rns_exact(&params, &chain, &ciphertext, &mask_plaintext)
                .expect("multiply by packed plaintext mask through RNS");
        assert_eq!(rns_masked, masked);
        let masked_plaintext =
            decrypt(&params, &secret_key, &rns_masked).expect("decrypt packed mask output");
        let masked_slots =
            decode_packed_plaintext_slots(&params, &masked_plaintext).expect("decode slots");
        let expected_slots = slots
            .iter()
            .copied()
            .zip(mask_slots.iter().copied())
            .map(|(slot, mask)| slot * mask)
            .collect::<Vec<_>>();
        assert_eq!(masked_slots, expected_slots);

        let (bounded_secret_key, bounded_public_key) =
            keygen_bounded_noise_from_seed(&params, b"bfv-bounded-packed-mask-keygen")
                .expect("bounded-noise keygen");
        let bounded_ciphertext = encrypt_bounded_noise_from_seed(
            &params,
            &bounded_public_key,
            &packed_plaintext,
            b"bfv-bounded-packed-mask-input",
        )
        .expect("encrypt bounded packed input");
        let bounded_masked = multiply_plaintext_polynomial_bounded_noise(
            &params,
            &bounded_ciphertext,
            &mask_plaintext,
        )
        .expect("multiply bounded ciphertext by packed plaintext mask");
        let bounded_rns_masked = multiply_plaintext_polynomial_bounded_noise_rns_exact(
            &params,
            &chain,
            &bounded_ciphertext,
            &mask_plaintext,
        )
        .expect("multiply bounded ciphertext by packed plaintext mask through RNS");
        assert_eq!(bounded_rns_masked, bounded_masked);
        let bounded_masked_plaintext =
            decrypt_bounded_noise(&params, &bounded_secret_key, &bounded_rns_masked)
                .expect("decrypt bounded packed mask output");
        let bounded_masked_slots =
            decode_packed_plaintext_slots(&params, &bounded_masked_plaintext)
                .expect("decode bounded slots");
        assert_eq!(bounded_masked_slots, expected_slots);
    }

    #[test]
    fn homomorphic_ciphertext_multiplication_matches_plaintext() {
        let params = params();
        let (secret_key, public_key, relin_key) =
            keygen_from_seed(&params, b"bfv-ct-mul-keygen").expect("keygen");
        let lhs =
            encrypt_from_seed(&params, &public_key, &[7], b"bfv-ct-mul-left").expect("enc lhs");
        let rhs =
            encrypt_from_seed(&params, &public_key, &[9], b"bfv-ct-mul-right").expect("enc rhs");
        let encoded_product = poly_mul_mod(
            &params,
            &encode_plaintext(&params, &[7]),
            &encode_plaintext(&params, &[9]),
        );
        let encoded_plaintext = decode_plaintext(&params, &encoded_product);
        assert_eq!(encoded_plaintext[0], 63);
        let raw_c0 = poly_mul_mod(&params, &lhs.c0, &rhs.c0);
        let raw_c1 = poly_add_mod(
            &params,
            &poly_mul_mod(&params, &lhs.c0, &rhs.c1),
            &poly_mul_mod(&params, &lhs.c1, &rhs.c0),
        );
        let raw_c2 = poly_mul_mod(&params, &lhs.c1, &rhs.c1);
        let raw_scaled = poly_add_mod(
            &params,
            &raw_c0,
            &poly_add_mod(
                &params,
                &poly_mul_mod(&params, &raw_c1, &secret_key.s),
                &poly_mul_mod(
                    &params,
                    &raw_c2,
                    &poly_mul_mod(&params, &secret_key.s, &secret_key.s),
                ),
            ),
        );
        let raw_plaintext = decode_plaintext(&params, &raw_scaled);
        assert_eq!(raw_plaintext[0], 63);
        let product = multiply_ciphertexts(&params, &relin_key, &lhs, &rhs).expect("multiply");
        let plaintext = decrypt(&params, &secret_key, &product).expect("decrypt");
        assert_eq!(plaintext[0], 63);
    }

